option.value:
package me.allync.blockregen.listener;

import com.sk89q.worldedit.bukkit.BukkitAdapter;
import com.sk89q.worldguard.LocalPlayer;
import com.sk89q.worldguard.WorldGuard;
import com.sk89q.worldguard.bukkit.WorldGuardPlugin;
import com.sk89q.worldguard.protection.flags.Flags;
import com.sk89q.worldguard.protection.regions.RegionContainer;
import com.sk89q.worldguard.protection.regions.RegionQuery;
import me.allync.blockregen.BlockRegen;
import me.allync.blockregen.data.BlockData;
import me.allync.blockregen.data.MiningProgressState;
import me.allync.blockregen.data.MiningTargetKey;
import me.allync.blockregen.data.ToolRequirement;
import me.allync.blockregen.manager.MiningManager;
import me.allync.blockregen.task.PlayerHealthMiningTask;
import me.allync.blockregen.task.PlayerMiningTask;
import me.allync.blockregen.util.ItemUtil;
import me.allync.blockregen.util.SoundUtil;
import org.bukkit.GameMode;
import org.bukkit.Material;
import org.bukkit.block.Block;
import org.bukkit.block.BlockFace;
import org.bukkit.entity.Player;
import org.bukkit.event.EventHandler;
import org.bukkit.event.EventPriority;
import org.bukkit.event.Listener;
import org.bukkit.event.block.Action;
import org.bukkit.event.player.PlayerChangedWorldEvent;
import org.bukkit.event.player.PlayerInteractEvent;
import org.bukkit.event.player.PlayerKickEvent;
import org.bukkit.event.player.PlayerQuitEvent;
import org.bukkit.event.player.PlayerTeleportEvent;
import org.bukkit.event.entity.PlayerDeathEvent;
import org.bukkit.inventory.ItemStack;
import org.bukkit.permissions.PermissionAttachmentInfo;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.UUID;

/**
 * Listener untuk sistem penambangan kustom dengan durasi.
 * Mekanisme: pemain klik KIRI/ KANAN pada blok health untuk memulai & melanjutkan penambangan.
 * Setiap klik = satu "hit". Jika berhenti klik > hold-timeout-ms, mining dibatalkan.
 * Fitur Stackable: Jika ada blok berdampingan dengan konfigurasi sama, semua ikut dibreak.
 */
public class BlockMiningListener implements Listener {

    private static final String TOUCH_PERMISSION_PREFIX = "blockregen.multiplier.block.";

    private final BlockRegen plugin;
    private final MiningManager miningManager;

    private final Map<UUID, PlayerMiningTask> activeMiningTasks = new HashMap<>();
    private final Map<UUID, PlayerHealthMiningTask> activeHealthTasks = new HashMap<>();
    private final Map<MiningTargetKey, UUID> activeBlockMiners = new HashMap<>();
    private final Map<UUID, Long> mineConflictMessageCooldown = new HashMap<>();
    private final Map<MiningTargetKey, MiningProgressState> persistedProgress = new HashMap<>();
    private final Map<UUID, Map<MiningTargetKey, Long>> playerTouchedBlocks = new HashMap<>();

    public BlockMiningListener(BlockRegen plugin) {
        this.plugin = plugin;
        this.miningManager = plugin.getMiningManager();
    }

    // ─────────────────────────────────────────────────────────────────────────
    // MAIN EVENT: LEFT/RIGHT-CLICK BLOCK
    // ─────────────────────────────────────────────────────────────────────────

    @EventHandler(priority = EventPriority.HIGH, ignoreCancelled = true)
    public void onPlayerInteract(PlayerInteractEvent event) {
        // Hanya proses klik kiri/kanan pada blok
        Action action = event.getAction();
        if (action != Action.LEFT_CLICK_BLOCK && action != Action.RIGHT_CLICK_BLOCK) return;
        Block block = event.getClickedBlock();
        if (block == null) return;

        Player player = event.getPlayer();

        // --- 1. Initial Checks ---
        if (player.getGameMode() != GameMode.SURVIVAL) return;
        if (!plugin.getConfigManager().allWorldsEnabled
                && !plugin.getConfigManager().enabledWorlds.contains(player.getWorld().getName())) return;

        if (BlockRegen.harvestFlowEnabled) {
            Material blockType = block.getType();
            if (blockType == Material.WHEAT || blockType == Material.CARROTS
                    || blockType == Material.POTATOES || blockType == Material.BEETROOTS
                    || blockType == Material.NETHER_WART || blockType == Material.COCOA) {
                return;
            }
        }

        Set<String> regionNames = plugin.getRegionManager().getRegionNamesAt(block.getLocation());
        String blockIdentifier = miningManager.getBlockIdentifier(block, regionNames);

        // --- 2. Get BlockData & dispatch by mode ---
        BlockData data = plugin.getBlockManager().getBlockData(blockIdentifier, regionNames);
        if (data == null) return; // Bukan regen block

        // Mode health-based: setiap klik kiri/kanan mengurangi HP
        if (data.hasBlockHealth()) {
            event.setCancelled(true);
            handleHealthBlock(player, block, data, blockIdentifier);
            return;
        }

        if (!data.hasCustomBreakDuration()) {
            // BlockBreakListener yang menangani (vanilla break / instant break)
            return;
        }

        // Cegah interaction bawaan (misal: membuka chest, dll) saat mining
        event.setCancelled(true);

        UUID uuid = player.getUniqueId();
        MiningTargetKey blockKey = MiningTargetKey.from(block.getLocation());

        cleanupExpiredProgress(blockKey);

        // Jika player sudah mining blok tertentu —
        PlayerMiningTask existingTask = activeMiningTasks.get(uuid);
        if (existingTask != null) {
            if (!existingTask.getBlockLocation().equals(block.getLocation())) {
                // Klik blok berbeda → batalkan yang lama
                miningManager.debug(player, blockIdentifier, "&cSwitching target block. Cancelling old task.");
                existingTask.cancelTask();
                // lanjut untuk mulai task baru
            } else {
                // Klik blok yang sama → daftarkan hit supaya timer tidak timeout
                existingTask.registerHit();
                return;
            }
        }

        if (!canPlayerTouchBlock(player, blockKey)) {
            player.sendMessage(plugin.getConfigManager().touchLimitReachedMessage);
            return;
        }

        UUID ownerUuid = activeBlockMiners.get(blockKey);
        if (ownerUuid != null && !ownerUuid.equals(uuid)) {
            PlayerMiningTask ownerTask = activeMiningTasks.get(ownerUuid);
            if (ownerTask == null) {
                activeBlockMiners.remove(blockKey); // stale lock
            } else {
                maybeSendMineConflictMessage(player);
                return;
            }
        }

        // --- 3. WorldGuard Checks ---
        if (plugin.getConfigManager().worldGuardEnabled && plugin.getWorldGuardPlugin() != null) {
            LocalPlayer localPlayer = WorldGuardPlugin.inst().wrapPlayer(player);
            RegionContainer container = WorldGuard.getInstance().getPlatform().getRegionContainer();
            RegionQuery query = container.createQuery();
            boolean canBreak = query.testBuild(BukkitAdapter.adapt(block.getLocation()), localPlayer, Flags.BLOCK_BREAK);

            if (!canBreak) {
                if (!plugin.getConfigManager().worldGuardBreakRegenInDenyRegions) {
                    miningManager.debug(player, blockIdentifier, "WorldGuard check &cfailed&7 (block-break: DENY).");
                    return;
                }
            } else {
                if (plugin.getConfigManager().worldGuardDisableOtherBreak) {
                    if (!plugin.getBlockManager().isRegenBlockInRegion(blockIdentifier, regionNames)) {
                        if (!plugin.isPlayerBypassing(player)) {
                            miningManager.debug(player, blockIdentifier, "Block is not a regen block. &cCancelling due to WG config.");
                            return;
                        }
                    }
                }
            }
        }

        // --- 4. Region / Regenerating checks ---
        boolean inSupportedRegion = plugin.getConfigManager().worldGuardEnabled
                ? plugin.getRegionManager().isLocationInAnySupportedRegion(block.getLocation())
                : plugin.getRegionManager().isLocationInRegion(block.getLocation());
        if (!inSupportedRegion) {
            miningManager.debug(player, blockIdentifier, "Location is not inside a supported region. &cIgnoring.");
            return;
        }

        // isRegenerating check removed to allow progressive mining

        // --- 5. Pickaxe Power & Tool Checks ---
        double power = (data.requiresPickaxePower() || data.requiresTool())
                ? ItemUtil.getPickaxePower(player.getInventory().getItemInMainHand())
                : 0.0;

        if (data.requiresPickaxePower() || data.requiresTool()) {
            miningManager.debug(player, blockIdentifier, "&7Pickaxe power terdeteksi: &f" + power
                    + (data.requiresPickaxePower() ? " &7(req: &f" + data.getRequirePickaxePower() + "&7)" : ""));
        }

        if (data.requiresTool()) {
            ItemStack itemInHand = player.getInventory().getItemInMainHand();
            boolean toolMatches = false;
            for (ToolRequirement requirement : data.getRequiredTools()) {
                if (requirement.matches(itemInHand)) {
                    toolMatches = true;
                    break;
                }
            }
            if (!toolMatches && data.requiresPickaxePower() && power >= data.getRequirePickaxePower()) {
                toolMatches = true;
                miningManager.debug(player, blockIdentifier, "&aTool requirement met via pickaxe power (" + power + " >= " + data.getRequirePickaxePower() + ")");
            }
            if (!toolMatches) {
                miningManager.debug(player, blockIdentifier, "&cTool requirement not met.");
                String requiredTools = miningManager.formatRequiredTools(data);
                player.sendMessage(plugin.getConfigManager().wrongToolMessage.replace("%tool%", requiredTools));
                SoundUtil.playSoundToPlayer(player, block.getLocation(), plugin.getConfigManager().wrongToolSound, null);
                return;
            }
        }

        if (data.requiresPickaxePower()) {
            if (power < data.getRequirePickaxePower()) {
                miningManager.debug(player, blockIdentifier, "&cPickaxe power too low (" + power + " < " + data.getRequirePickaxePower() + ")");
                String reqStr = String.valueOf((int) data.getRequirePickaxePower());
                String curStr = String.format("%.1f", power);
                String msg = plugin.getConfigManager().lowPickaxePowerMessage
                        .replace("%power%", reqStr)
                        .replace("%your_power%", curStr);
                player.sendMessage(msg);
                SoundUtil.playSoundToPlayer(player, block.getLocation(), plugin.getConfigManager().wrongToolSound, null);
                return;
            }
            miningManager.debug(player, blockIdentifier, "&aPickaxe power requirement met (" + power + " >= " + data.getRequirePickaxePower() + ")");
        }

        // --- 6. Cari blok stackable berdampingan ---
        List<Block> stackedBlocks;
        if (plugin.getConfigManager().stackableBlocksEnabled) {
            stackedBlocks = findStackedBlocks(block, blockIdentifier);
            miningManager.debug(player, blockIdentifier, "&7Stack: " + stackedBlocks.size() + " blok terdeteksi (termasuk blok utama).");
        } else {
            stackedBlocks = new java.util.ArrayList<>();
            stackedBlocks.add(block);
        }

        // --- 7. Start Task ---
        miningManager.debug(player, blockIdentifier, "Started mining. Duration: " + data.getBreakDuration() + "s");
        registerTouch(player, blockKey);

        long resumedElapsedMs = 0L;
        MiningProgressState savedState = persistedProgress.get(blockKey);
        if (savedState != null) {
            resumedElapsedMs = savedState.getElapsedMs();
        }

        activeBlockMiners.put(blockKey, uuid);
        PlayerMiningTask newTask = new PlayerMiningTask(
                plugin,
                player,
                block,
                data,
                blockIdentifier,
                activeMiningTasks,
                activeBlockMiners,
                persistedProgress,
                blockKey,
                resumedElapsedMs,
                null,
                stackedBlocks    // ← daftar blok stackable
        );
        newTask.runTaskTimer(plugin, 0L, 1L);
        activeMiningTasks.put(uuid, newTask);
    }

    // ─────────────────────────────────────────────────────────────────────────
    // ─────────────────────────────────────────────────────────────────────────
    // HEALTH BLOCK LOGIC
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * Proses hit pada blok mode health.
     * Setiap klik kiri/kanan mengurangi HP blok sebesar pickaxe power pemain.
     */
    private void handleHealthBlock(Player player, Block block, BlockData data,
                                   String blockIdentifier) {
        UUID uuid = player.getUniqueId();

        ItemStack itemInHand = player.getInventory().getItemInMainHand();
        double power = (data.requiresPickaxePower() || data.requiresTool())
                ? ItemUtil.getPickaxePower(itemInHand)
                : 0.0;

        if (data.requiresTool()) {
            boolean toolMatches = false;
            for (ToolRequirement requirement : data.getRequiredTools()) {
                if (requirement.matches(itemInHand)) {
                    toolMatches = true;
                    break;
                }
            }
            if (!toolMatches && data.requiresPickaxePower() && power >= data.getRequirePickaxePower()) {
                toolMatches = true;
            }
            if (!toolMatches) {
                String requiredTools = miningManager.formatRequiredTools(data);
                player.sendMessage(plugin.getConfigManager().wrongToolMessage.replace("%tool%", requiredTools));
                SoundUtil.playSoundToPlayer(player, block.getLocation(), plugin.getConfigManager().wrongToolSound, null);
                return;
            }
        }

        if (data.requiresPickaxePower() && power < data.getRequirePickaxePower()) {
            String reqStr = String.valueOf((int) data.getRequirePickaxePower());
            String curStr = String.format("%.1f", power);
            player.sendMessage(plugin.getConfigManager().lowPickaxePowerMessage
                    .replace("%power%", reqStr)
                    .replace("%your_power%", curStr));
            SoundUtil.playSoundToPlayer(player, block.getLocation(), plugin.getConfigManager().wrongToolSound, null);
            return;
        }

        // Anti auto-clicker: jika pemain sudah punya task health yang berjalan untuk blok ini, abaikan klik ini.
        PlayerHealthMiningTask existingTask = activeHealthTasks.get(uuid);
        if (existingTask != null) {
            if (existingTask.getBlock().getLocation().equals(block.getLocation())) {
                return; // Sedang menambang blok ini, abaikan klik tambahan
            } else {
                existingTask.cancelTask(); // Ganti blok, batalkan task lama
            }
        }

        // Mulai task baru yang akan berjalan otomatis per detik
        PlayerHealthMiningTask newTask = new PlayerHealthMiningTask(
                plugin, player, block, data, blockIdentifier, activeHealthTasks
        );
        newTask.runTaskTimer(plugin, 0L, 1L); // Cek target tiap tick, damage tiap 20 tick (1s)
        activeHealthTasks.put(uuid, newTask);

        miningManager.debug(player, blockIdentifier, "&a[Health] Auto-mining started. Keep looking at the block!");
    }

    // ─────────────────────────────────────────────────────────────────────────
    // STACKABLE BLOCK LOGIC
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * Mencari blok-blok berdampingan (6 arah face) yang memiliki blockIdentifier sama
     * dan merupakan regen block yang valid. Menggunakan BFS agar bisa menemukan cluster.
     *
     * @param origin          Blok asal
     * @param blockIdentifier ID blok yang sedang ditambang
     * @return Daftar blok (termasuk origin), maksimal MAX_STACK_SIZE buah
     */
    private List<Block> findStackedBlocks(Block origin, String blockIdentifier) {
        int maxSize = plugin.getConfigManager().stackableBlocksMaxSize;
        List<Block> result = new ArrayList<>();
        result.add(origin);

        // BFS — cari blok tetangga dengan tipe sama
        List<Block> queue = new ArrayList<>();
        queue.add(origin);
        Set<String> visited = new java.util.HashSet<>();
        visited.add(locationKey(origin));

        BlockFace[] faces = {
            BlockFace.NORTH, BlockFace.SOUTH,
            BlockFace.EAST,  BlockFace.WEST,
            BlockFace.UP,    BlockFace.DOWN
        };

        while (!queue.isEmpty() && result.size() < maxSize) {
            Block current = queue.remove(0);
            for (BlockFace face : faces) {
                if (result.size() >= maxSize) break;
                Block neighbor = current.getRelative(face);
                String key = locationKey(neighbor);
                if (visited.contains(key)) continue;
                visited.add(key);

                String neighborId = miningManager.getBlockIdentifier(neighbor);
                if (!neighborId.equalsIgnoreCase(blockIdentifier)) continue;

                // Pastikan blok tetangga juga valid sebagai regen block
                Set<String> neighborRegions = plugin.getRegionManager().getRegionNamesAt(neighbor.getLocation());
                BlockData neighborData = plugin.getBlockManager().getBlockData(neighborId, neighborRegions);
                if (neighborData == null) continue;
                if (plugin.getRegenManager().isRegenerating(neighbor.getLocation())) continue;
                if (miningManager.isBeingMined(neighbor.getLocation())) continue;

                result.add(neighbor);
                queue.add(neighbor);
            }
        }

        return result;
    }

    private static String locationKey(Block block) {
        return block.getWorld().getName() + ":" + block.getX() + ":" + block.getY() + ":" + block.getZ();
    }

    // ─────────────────────────────────────────────────────────────────────────
    // PLAYER LIFECYCLE EVENTS
    // ─────────────────────────────────────────────────────────────────────────

    @EventHandler
    public void onPlayerQuit(PlayerQuitEvent event) {
        UUID uuid = event.getPlayer().getUniqueId();
        cancelTaskFor(uuid);
    }

    @EventHandler
    public void onPlayerKick(PlayerKickEvent event) {
        cancelTaskFor(event.getPlayer().getUniqueId());
    }

    @EventHandler
    public void onPlayerDeath(PlayerDeathEvent event) {
        cancelTaskFor(event.getEntity().getUniqueId());
    }

    @EventHandler(ignoreCancelled = true)
    public void onPlayerTeleport(PlayerTeleportEvent event) {
        if (event.getFrom().getWorld() == null || event.getTo() == null || event.getTo().getWorld() == null) {
            return;
        }
        if (!event.getFrom().getWorld().getUID().equals(event.getTo().getWorld().getUID())) {
            cancelTaskFor(event.getPlayer().getUniqueId());
        }
    }

    @EventHandler
    public void onPlayerChangedWorld(PlayerChangedWorldEvent event) {
        cancelTaskFor(event.getPlayer().getUniqueId());
    }

    @EventHandler
    public void onPlayerItemHeld(org.bukkit.event.player.PlayerItemHeldEvent event) {
        cancelTaskFor(event.getPlayer().getUniqueId(), true);
    }

    @EventHandler
    public void onPlayerDropItem(org.bukkit.event.player.PlayerDropItemEvent event) {
        cancelTaskFor(event.getPlayer().getUniqueId(), true);
    }

    // ─────────────────────────────────────────────────────────────────────────
    // HELPERS
    // ─────────────────────────────────────────────────────────────────────────

    private void maybeSendMineConflictMessage(Player player) {
        long now = System.currentTimeMillis();
        long lastSent = mineConflictMessageCooldown.getOrDefault(player.getUniqueId(), 0L);
        if (now - lastSent < 750L) return;
        mineConflictMessageCooldown.put(player.getUniqueId(), now);
        player.sendMessage(plugin.getConfigManager().blockBeingMinedMessage);
    }

    public void shutdown() {
        for (PlayerMiningTask task : activeMiningTasks.values()) {
            if (task != null) task.cancelTask();
        }
        for (PlayerHealthMiningTask task : activeHealthTasks.values()) {
            if (task != null) task.cancelTask();
        }
        activeMiningTasks.clear();
        activeHealthTasks.clear();
        activeBlockMiners.clear();
        mineConflictMessageCooldown.clear();
        playerTouchedBlocks.clear();
        persistedProgress.clear();
    }

    private void cancelTaskFor(UUID uuid) {
        cancelTaskFor(uuid, false);
    }

    private void cancelTaskFor(UUID uuid, boolean forceReset) {
        PlayerMiningTask existingTask = activeMiningTasks.get(uuid);
        if (existingTask != null) {
            if (forceReset) {
                persistedProgress.remove(MiningTargetKey.from(existingTask.getBlock().getLocation()));
            }
            existingTask.cancelTask();
        }
        PlayerHealthMiningTask existingHealthTask = activeHealthTasks.get(uuid);
        if (existingHealthTask != null) {
            if (forceReset) {
                plugin.getBlockHealthManager().reset(existingHealthTask.getBlock().getLocation());
            }
            existingHealthTask.cancelTask();
        }
        mineConflictMessageCooldown.remove(uuid);
        playerTouchedBlocks.remove(uuid);
    }

    public void resetProgress(org.bukkit.Location loc) {
        MiningTargetKey key = MiningTargetKey.from(loc);
        persistedProgress.remove(key);
        plugin.getBlockHealthManager().reset(loc);
    }

    private void cleanupExpiredProgress(MiningTargetKey blockKey) {
        MiningProgressState state = persistedProgress.get(blockKey);
        if (state == null) return;
        if (System.currentTimeMillis() - state.getUpdatedAtMs() > plugin.getConfigManager().miningResumeTimeoutMs) {
            persistedProgress.remove(blockKey);
        }
    }

    private boolean canPlayerTouchBlock(Player player, MiningTargetKey blockKey) {
        long now = System.currentTimeMillis();
        Map<MiningTargetKey, Long> touches = playerTouchedBlocks.computeIfAbsent(player.getUniqueId(), k -> new HashMap<>());
        touches.entrySet().removeIf(entry -> now - entry.getValue() > plugin.getConfigManager().miningResumeTimeoutMs);
        if (touches.containsKey(blockKey)) return true;
        int limit = getPlayerTouchLimit(player);
        return touches.size() < limit;
    }

    private void registerTouch(Player player, MiningTargetKey blockKey) {
        Map<MiningTargetKey, Long> touches = playerTouchedBlocks.computeIfAbsent(player.getUniqueId(), k -> new HashMap<>());
        touches.put(blockKey, System.currentTimeMillis());
    }

    private int getPlayerTouchLimit(Player player) {
        int limit = plugin.getConfigManager().miningDefaultTouchLimit;
        for (PermissionAttachmentInfo permissionInfo : player.getEffectivePermissions()) {
            if (!permissionInfo.getValue()) continue;
            String permission = permissionInfo.getPermission().toLowerCase();
            if (!permission.startsWith(TOUCH_PERMISSION_PREFIX)) continue;
            String valuePart = permission.substring(TOUCH_PERMISSION_PREFIX.length());
            try {
                int extra = Integer.parseInt(valuePart);
                if (extra > 0) limit += extra;
            } catch (NumberFormatException ignored) {}
        }
        return Math.max(plugin.getConfigManager().miningDefaultTouchLimit, limit);
    }

    public boolean isBlockBusy(org.bukkit.Location loc) {
        MiningTargetKey key = MiningTargetKey.from(loc);
        if (activeBlockMiners.containsKey(key)) return true;
        if (persistedProgress.containsKey(key)) {
            MiningProgressState state = persistedProgress.get(key);
            if (System.currentTimeMillis() - state.getUpdatedAtMs() < plugin.getConfigManager().miningResumeTimeoutMs) {
                return true;
            }
        }
        for (PlayerHealthMiningTask task : activeHealthTasks.values()) {
            if (task.getBlock().getLocation().equals(loc)) {
                return true;
            }
        }
        return false;
    }

    /**
     * Batalkan task mining di lokasi ini secara langsung.
     */
    public void cancelTaskAt(org.bukkit.Location loc) {
        if (loc == null) return;
        MiningTargetKey key = MiningTargetKey.from(loc);
        UUID miner = activeBlockMiners.get(key);
        if (miner != null) {
            PlayerMiningTask task = activeMiningTasks.get(miner);
            if (task != null) task.cancelTask();
        }
        for (PlayerHealthMiningTask task : activeHealthTasks.values()) {
            if (task.getBlock().getLocation().equals(loc)) {
                task.cancelTask();
                break;
            }
        }
        persistedProgress.remove(key);
        activeBlockMiners.remove(key);
    }

    public void cleanupPlayer(UUID uuid) {
        playerTouchedBlocks.remove(uuid);
        mineConflictMessageCooldown.remove(uuid);
    }
}

package me.allync.blockregen.listener;

import com.sk89q.worldedit.bukkit.BukkitAdapter;
import com.sk89q.worldguard.LocalPlayer;
import com.sk89q.worldguard.WorldGuard;
import com.sk89q.worldguard.bukkit.WorldGuardPlugin;
import com.sk89q.worldguard.protection.flags.Flags;
import com.sk89q.worldguard.protection.regions.RegionContainer;
import com.sk89q.worldguard.protection.regions.RegionQuery;
import me.allync.blockregen.BlockRegen;
import me.allync.blockregen.data.BlockData;
import me.allync.blockregen.data.MiningProgressState;
import me.allync.blockregen.data.MiningTargetKey;
import me.allync.blockregen.data.ToolRequirement;
import me.allync.blockregen.manager.MiningManager;
import me.allync.blockregen.task.PlayerHealthMiningTask;
import me.allync.blockregen.task.PlayerMiningTask;
import me.allync.blockregen.util.ItemUtil;
import me.allync.blockregen.util.SoundUtil;
import org.bukkit.GameMode;
import org.bukkit.Material;
import org.bukkit.block.Block;
import org.bukkit.block.BlockFace;
import org.bukkit.entity.Player;
import org.bukkit.event.EventHandler;
import org.bukkit.event.EventPriority;
import org.bukkit.event.Listener;
import org.bukkit.event.block.Action;
import org.bukkit.event.player.PlayerChangedWorldEvent;
import org.bukkit.event.player.PlayerInteractEvent;
import org.bukkit.event.player.PlayerKickEvent;
import org.bukkit.event.player.PlayerQuitEvent;
import org.bukkit.event.player.PlayerTeleportEvent;
import org.bukkit.event.entity.PlayerDeathEvent;
import org.bukkit.inventory.ItemStack;
import org.bukkit.permissions.PermissionAttachmentInfo;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.UUID;

/**
 * Listener untuk sistem penambangan kustom dengan durasi.
 * Mekanisme: pemain klik KIRI/ KANAN pada blok health untuk memulai & melanjutkan penambangan.
 * Setiap klik = satu "hit". Jika berhenti klik > hold-timeout-ms, mining dibatalkan.
 * Fitur Stackable: Jika ada blok berdampingan dengan konfigurasi sama, semua ikut dibreak.
 */
public class BlockMiningListener implements Listener {

    private static final String TOUCH_PERMISSION_PREFIX = "blockregen.multiplier.block.";

    private final BlockRegen plugin;
    private final MiningManager miningManager;

    private final Map<UUID, PlayerMiningTask> activeMiningTasks = new HashMap<>();
    private final Map<UUID, PlayerHealthMiningTask> activeHealthTasks = new HashMap<>();
    private final Map<MiningTargetKey, UUID> activeBlockMiners = new HashMap<>();
    private final Map<UUID, Long> mineConflictMessageCooldown = new HashMap<>();
    private final Map<MiningTargetKey, MiningProgressState> persistedProgress = new HashMap<>();
    private final Map<UUID, Map<MiningTargetKey, Long>> playerTouchedBlocks = new HashMap<>();

    public BlockMiningListener(BlockRegen plugin) {
        this.plugin = plugin;
        this.miningManager = plugin.getMiningManager();
    }

    // ─────────────────────────────────────────────────────────────────────────
    // MAIN EVENT: LEFT/RIGHT-CLICK BLOCK
    // ─────────────────────────────────────────────────────────────────────────

    @EventHandler(priority = EventPriority.HIGH, ignoreCancelled = true)
    public void onPlayerInteract(PlayerInteractEvent event) {
        // Hanya proses klik kiri/kanan pada blok
        Action action = event.getAction();
        if (action != Action.LEFT_CLICK_BLOCK && action != Action.RIGHT_CLICK_BLOCK) return;
        Block block = event.getClickedBlock();
        if (block == null) return;

        Player player = event.getPlayer();

        // --- 1. Initial Checks ---
        if (player.getGameMode() != GameMode.SURVIVAL) return;
        if (!plugin.getConfigManager().allWorldsEnabled
                && !plugin.getConfigManager().enabledWorlds.contains(player.getWorld().getName())) return;

        if (BlockRegen.harvestFlowEnabled) {
            Material blockType = block.getType();
            if (blockType == Material.WHEAT || blockType == Material.CARROTS
                    || blockType == Material.POTATOES || blockType == Material.BEETROOTS
                    || blockType == Material.NETHER_WART || blockType == Material.COCOA) {
                return;
            }
        }

        Set<String> regionNames = plugin.getRegionManager().getRegionNamesAt(block.getLocation());
        String blockIdentifier = miningManager.getBlockIdentifier(block, regionNames);

        // --- 2. Get BlockData & dispatch by mode ---
        BlockData data = plugin.getBlockManager().getBlockData(blockIdentifier, regionNames);
        if (data == null) return; // Bukan regen block

        // Mode health-based: setiap klik kiri/kanan mengurangi HP
        if (data.hasBlockHealth()) {
            event.setCancelled(true);
            handleHealthBlock(player, block, data, blockIdentifier);
            return;
        }

        if (!data.hasCustomBreakDuration()) {
            // BlockBreakListener yang menangani (vanilla break / instant break)
            return;
        }

        // Cegah interaction bawaan (misal: membuka chest, dll) saat mining
        event.setCancelled(true);

        UUID uuid = player.getUniqueId();
        MiningTargetKey blockKey = MiningTargetKey.from(block.getLocation());

        cleanupExpiredProgress(blockKey);

        // Jika player sudah mining blok tertentu —
        PlayerMiningTask existingTask = activeMiningTasks.get(uuid);
        if (existingTask != null) {
            if (!existingTask.getBlockLocation().equals(block.getLocation())) {
                // Klik blok berbeda → batalkan yang lama
                miningManager.debug(player, blockIdentifier, "&cSwitching target block. Cancelling old task.");
                existingTask.cancelTask();
                // lanjut untuk mulai task baru
            } else {
                // Klik blok yang sama → daftarkan hit supaya timer tidak timeout
                existingTask.registerHit();
                return;
            }
        }

        if (!canPlayerTouchBlock(player, blockKey)) {
            player.sendMessage(plugin.getConfigManager().touchLimitReachedMessage);
            return;
        }

        UUID ownerUuid = activeBlockMiners.get(blockKey);
        if (ownerUuid != null && !ownerUuid.equals(uuid)) {
            PlayerMiningTask ownerTask = activeMiningTasks.get(ownerUuid);
            if (ownerTask == null) {
                activeBlockMiners.remove(blockKey); // stale lock
            } else {
                maybeSendMineConflictMessage(player);
                return;
            }
        }

        // --- 3. WorldGuard Checks ---
        if (plugin.getConfigManager().worldGuardEnabled && plugin.getWorldGuardPlugin() != null) {
            LocalPlayer localPlayer = WorldGuardPlugin.inst().wrapPlayer(player);
            RegionContainer container = WorldGuard.getInstance().getPlatform().getRegionContainer();
            RegionQuery query = container.createQuery();
            boolean canBreak = query.testBuild(BukkitAdapter.adapt(block.getLocation()), localPlayer, Flags.BLOCK_BREAK);

            if (!canBreak) {
                if (!plugin.getConfigManager().worldGuardBreakRegenInDenyRegions) {
                    miningManager.debug(player, blockIdentifier, "WorldGuard check &cfailed&7 (block-break: DENY).");
                    return;
                }
            } else {
                if (plugin.getConfigManager().worldGuardDisableOtherBreak) {
                    if (!plugin.getBlockManager().isRegenBlockInRegion(blockIdentifier, regionNames)) {
                        if (!plugin.isPlayerBypassing(player)) {
                            miningManager.debug(player, blockIdentifier, "Block is not a regen block. &cCancelling due to WG config.");
                            return;
                        }
                    }
                }
            }
        }

        // --- 4. Region / Regenerating checks ---
        boolean inSupportedRegion = plugin.getConfigManager().worldGuardEnabled
                ? plugin.getRegionManager().isLocationInAnySupportedRegion(block.getLocation())
                : plugin.getRegionManager().isLocationInRegion(block.getLocation());
        if (!inSupportedRegion) {
            miningManager.debug(player, blockIdentifier, "Location is not inside a supported region. &cIgnoring.");
            return;
        }

        // isRegenerating check removed to allow progressive mining

        // --- 5. Pickaxe Power & Tool Checks ---
        double power = (data.requiresPickaxePower() || data.requiresTool())
                ? ItemUtil.getPickaxePower(player.getInventory().getItemInMainHand())
                : 0.0;

        if (data.requiresPickaxePower() || data.requiresTool()) {
            miningManager.debug(player, blockIdentifier, "&7Pickaxe power terdeteksi: &f" + power
                    + (data.requiresPickaxePower() ? " &7(req: &f" + data.getRequirePickaxePower() + "&7)" : ""));
        }

        if (data.requiresTool()) {
            ItemStack itemInHand = player.getInventory().getItemInMainHand();
            boolean toolMatches = false;
            for (ToolRequirement requirement : data.getRequiredTools()) {
                if (requirement.matches(itemInHand)) {
                    toolMatches = true;
                    break;
                }
            }
            if (!toolMatches && data.requiresPickaxePower() && power >= data.getRequirePickaxePower()) {
                toolMatches = true;
                miningManager.debug(player, blockIdentifier, "&aTool requirement met via pickaxe power (" + power + " >= " + data.getRequirePickaxePower() + ")");
            }
            if (!toolMatches) {
                miningManager.debug(player, blockIdentifier, "&cTool requirement not met.");
                String requiredTools = miningManager.formatRequiredTools(data);
                player.sendMessage(plugin.getConfigManager().wrongToolMessage.replace("%tool%", requiredTools));
                SoundUtil.playSoundToPlayer(player, block.getLocation(), plugin.getConfigManager().wrongToolSound, null);
                return;
            }
        }

        if (data.requiresPickaxePower()) {
            if (power < data.getRequirePickaxePower()) {
                miningManager.debug(player, blockIdentifier, "&cPickaxe power too low (" + power + " < " + data.getRequirePickaxePower() + ")");
                String reqStr = String.valueOf((int) data.getRequirePickaxePower());
                String curStr = String.format("%.1f", power);
                String msg = plugin.getConfigManager().lowPickaxePowerMessage
                        .replace("%power%", reqStr)
                        .replace("%your_power%", curStr);
                player.sendMessage(msg);
                SoundUtil.playSoundToPlayer(player, block.getLocation(), plugin.getConfigManager().wrongToolSound, null);
                return;
            }
            miningManager.debug(player, blockIdentifier, "&aPickaxe power requirement met (" + power + " >= " + data.getRequirePickaxePower() + ")");
        }

        // --- 6. Cari blok stackable berdampingan ---
        List<Block> stackedBlocks;
        if (plugin.getConfigManager().stackableBlocksEnabled) {
            stackedBlocks = findStackedBlocks(block, blockIdentifier);
            miningManager.debug(player, blockIdentifier, "&7Stack: " + stackedBlocks.size() + " blok terdeteksi (termasuk blok utama).");
        } else {
            stackedBlocks = new java.util.ArrayList<>();
            stackedBlocks.add(block);
        }

        // --- 7. Start Task ---
        miningManager.debug(player, blockIdentifier, "Started mining. Duration: " + data.getBreakDuration() + "s");
        registerTouch(player, blockKey);

        long resumedElapsedMs = 0L;
        MiningProgressState savedState = persistedProgress.get(blockKey);
        if (savedState != null) {
            resumedElapsedMs = savedState.getElapsedMs();
        }

        activeBlockMiners.put(blockKey, uuid);
        PlayerMiningTask newTask = new PlayerMiningTask(
                plugin,
                player,
                block,
                data,
                blockIdentifier,
                activeMiningTasks,
                activeBlockMiners,
                persistedProgress,
                blockKey,
                resumedElapsedMs,
                null,
                stackedBlocks    // ← daftar blok stackable
        );
        newTask.runTaskTimer(plugin, 0L, 1L);
        activeMiningTasks.put(uuid, newTask);
    }

    // ─────────────────────────────────────────────────────────────────────────
    // ─────────────────────────────────────────────────────────────────────────
    // HEALTH BLOCK LOGIC
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * Proses hit pada blok mode health.
     * Setiap klik kiri/kanan mengurangi HP blok sebesar pickaxe power pemain.
     */
    private void handleHealthBlock(Player player, Block block, BlockData data,
                                   String blockIdentifier) {
        UUID uuid = player.getUniqueId();

        ItemStack itemInHand = player.getInventory().getItemInMainHand();
        double power = (data.requiresPickaxePower() || data.requiresTool())
                ? ItemUtil.getPickaxePower(itemInHand)
                : 0.0;

        if (data.requiresTool()) {
            boolean toolMatches = false;
            for (ToolRequirement requirement : data.getRequiredTools()) {
                if (requirement.matches(itemInHand)) {
                    toolMatches = true;
                    break;
                }
            }
            if (!toolMatches && data.requiresPickaxePower() && power >= data.getRequirePickaxePower()) {
                toolMatches = true;
            }
            if (!toolMatches) {
                String requiredTools = miningManager.formatRequiredTools(data);
                player.sendMessage(plugin.getConfigManager().wrongToolMessage.replace("%tool%", requiredTools));
                SoundUtil.playSoundToPlayer(player, block.getLocation(), plugin.getConfigManager().wrongToolSound, null);
                return;
            }
        }

        if (data.requiresPickaxePower() && power < data.getRequirePickaxePower()) {
            String reqStr = String.valueOf((int) data.getRequirePickaxePower());
            String curStr = String.format("%.1f", power);
            player.sendMessage(plugin.getConfigManager().lowPickaxePowerMessage
                    .replace("%power%", reqStr)
                    .replace("%your_power%", curStr));
            SoundUtil.playSoundToPlayer(player, block.getLocation(), plugin.getConfigManager().wrongToolSound, null);
            return;
        }

        // Anti auto-clicker: jika pemain sudah punya task health yang berjalan untuk blok ini, abaikan klik ini.
        PlayerHealthMiningTask existingTask = activeHealthTasks.get(uuid);
        if (existingTask != null) {
            if (existingTask.getBlock().getLocation().equals(block.getLocation())) {
                return; // Sedang menambang blok ini, abaikan klik tambahan
            } else {
                existingTask.cancelTask(); // Ganti blok, batalkan task lama
            }
        }

        // Mulai task baru yang akan berjalan otomatis per detik
        PlayerHealthMiningTask newTask = new PlayerHealthMiningTask(
                plugin, player, block, data, blockIdentifier, activeHealthTasks
        );
        newTask.runTaskTimer(plugin, 0L, 1L); // Cek target tiap tick, damage tiap 20 tick (1s)
        activeHealthTasks.put(uuid, newTask);

        miningManager.debug(player, blockIdentifier, "&a[Health] Auto-mining started. Keep looking at the block!");
    }

    // ─────────────────────────────────────────────────────────────────────────
    // STACKABLE BLOCK LOGIC
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * Mencari blok-blok berdampingan (6 arah face) yang memiliki blockIdentifier sama
     * dan merupakan regen block yang valid. Menggunakan BFS agar bisa menemukan cluster.
     *
     * @param origin          Blok asal
     * @param blockIdentifier ID blok yang sedang ditambang
     * @return Daftar blok (termasuk origin), maksimal MAX_STACK_SIZE buah
     */
    private List<Block> findStackedBlocks(Block origin, String blockIdentifier) {
        int maxSize = plugin.getConfigManager().stackableBlocksMaxSize;
        List<Block> result = new ArrayList<>();
        result.add(origin);

        // BFS — cari blok tetangga dengan tipe sama
        List<Block> queue = new ArrayList<>();
        queue.add(origin);
        Set<String> visited = new java.util.HashSet<>();
        visited.add(locationKey(origin));

        BlockFace[] faces = {
            BlockFace.NORTH, BlockFace.SOUTH,
            BlockFace.EAST,  BlockFace.WEST,
            BlockFace.UP,    BlockFace.DOWN
        };

        while (!queue.isEmpty() && result.size() < maxSize) {
            Block current = queue.remove(0);
            for (BlockFace face : faces) {
                if (result.size() >= maxSize) break;
                Block neighbor = current.getRelative(face);
                String key = locationKey(neighbor);
                if (visited.contains(key)) continue;
                visited.add(key);

                Set<String> neighborRegions = plugin.getRegionManager().getRegionNamesAt(neighbor.getLocation());
                String neighborId = miningManager.getBlockIdentifier(neighbor, neighborRegions);
                if (!neighborId.equalsIgnoreCase(blockIdentifier)) continue;

                // Pastikan blok tetangga juga valid sebagai regen block
                BlockData neighborData = plugin.getBlockManager().getBlockData(neighborId, neighborRegions);
                if (neighborData == null) continue;
                if (plugin.getRegenManager().isRegenerating(neighbor.getLocation())) continue;
                if (miningManager.isBeingMined(neighbor.getLocation())) continue;

                result.add(neighbor);
                queue.add(neighbor);
            }
        }

        return result;
    }

    private static String locationKey(Block block) {
        return block.getWorld().getName() + ":" + block.getX() + ":" + block.getY() + ":" + block.getZ();
    }

    // ─────────────────────────────────────────────────────────────────────────
    // PLAYER LIFECYCLE EVENTS
    // ─────────────────────────────────────────────────────────────────────────

    @EventHandler
    public void onPlayerQuit(PlayerQuitEvent event) {
        UUID uuid = event.getPlayer().getUniqueId();
        cancelTaskFor(uuid);
    }

    @EventHandler
    public void onPlayerKick(PlayerKickEvent event) {
        cancelTaskFor(event.getPlayer().getUniqueId());
    }

    @EventHandler
    public void onPlayerDeath(PlayerDeathEvent event) {
        cancelTaskFor(event.getEntity().getUniqueId());
    }

    @EventHandler(ignoreCancelled = true)
    public void onPlayerTeleport(PlayerTeleportEvent event) {
        if (event.getFrom().getWorld() == null || event.getTo() == null || event.getTo().getWorld() == null) {
            return;
        }
        if (!event.getFrom().getWorld().getUID().equals(event.getTo().getWorld().getUID())) {
            cancelTaskFor(event.getPlayer().getUniqueId());
        }
    }

    @EventHandler
    public void onPlayerChangedWorld(PlayerChangedWorldEvent event) {
        cancelTaskFor(event.getPlayer().getUniqueId());
    }

    @EventHandler
    public void onPlayerItemHeld(org.bukkit.event.player.PlayerItemHeldEvent event) {
        cancelTaskFor(event.getPlayer().getUniqueId(), true);
    }

    @EventHandler
    public void onPlayerDropItem(org.bukkit.event.player.PlayerDropItemEvent event) {
        cancelTaskFor(event.getPlayer().getUniqueId(), true);
    }

    // ─────────────────────────────────────────────────────────────────────────
    // HELPERS
    // ─────────────────────────────────────────────────────────────────────────

    private void maybeSendMineConflictMessage(Player player) {
        long now = System.currentTimeMillis();
        long lastSent = mineConflictMessageCooldown.getOrDefault(player.getUniqueId(), 0L);
        if (now - lastSent < 750L) return;
        mineConflictMessageCooldown.put(player.getUniqueId(), now);
        player.sendMessage(plugin.getConfigManager().blockBeingMinedMessage);
    }

    public void shutdown() {
        for (PlayerMiningTask task : activeMiningTasks.values()) {
            if (task != null) task.cancelTask();
        }
        for (PlayerHealthMiningTask task : activeHealthTasks.values()) {
            if (task != null) task.cancelTask();
        }
        activeMiningTasks.clear();
        activeHealthTasks.clear();
        activeBlockMiners.clear();
        mineConflictMessageCooldown.clear();
        playerTouchedBlocks.clear();
        persistedProgress.clear();
    }

    private void cancelTaskFor(UUID uuid) {
        cancelTaskFor(uuid, false);
    }

    private void cancelTaskFor(UUID uuid, boolean forceReset) {
        PlayerMiningTask existingTask = activeMiningTasks.get(uuid);
        if (existingTask != null) {
            if (forceReset) {
                persistedProgress.remove(MiningTargetKey.from(existingTask.getBlock().getLocation()));
            }
            existingTask.cancelTask();
        }
        PlayerHealthMiningTask existingHealthTask = activeHealthTasks.get(uuid);
        if (existingHealthTask != null) {
            if (forceReset) {
                plugin.getBlockHealthManager().reset(existingHealthTask.getBlock().getLocation());
            }
            existingHealthTask.cancelTask();
        }
        mineConflictMessageCooldown.remove(uuid);
        playerTouchedBlocks.remove(uuid);
    }

    public void resetProgress(org.bukkit.Location loc) {
        MiningTargetKey key = MiningTargetKey.from(loc);
        persistedProgress.remove(key);
        plugin.getBlockHealthManager().reset(loc);
    }

    private void cleanupExpiredProgress(MiningTargetKey blockKey) {
        MiningProgressState state = persistedProgress.get(blockKey);
        if (state == null) return;
        if (System.currentTimeMillis() - state.getUpdatedAtMs() > plugin.getConfigManager().miningResumeTimeoutMs) {
            persistedProgress.remove(blockKey);
        }
    }

    private boolean canPlayerTouchBlock(Player player, MiningTargetKey blockKey) {
        long now = System.currentTimeMillis();
        Map<MiningTargetKey, Long> touches = playerTouchedBlocks.computeIfAbsent(player.getUniqueId(), k -> new HashMap<>());
        touches.entrySet().removeIf(entry -> now - entry.getValue() > plugin.getConfigManager().miningResumeTimeoutMs);
        if (touches.containsKey(blockKey)) return true;
        int limit = getPlayerTouchLimit(player);
        return touches.size() < limit;
    }

    private void registerTouch(Player player, MiningTargetKey blockKey) {
        Map<MiningTargetKey, Long> touches = playerTouchedBlocks.computeIfAbsent(player.getUniqueId(), k -> new HashMap<>());
        touches.put(blockKey, System.currentTimeMillis());
    }

    private int getPlayerTouchLimit(Player player) {
        int limit = plugin.getConfigManager().miningDefaultTouchLimit;
        for (PermissionAttachmentInfo permissionInfo : player.getEffectivePermissions()) {
            if (!permissionInfo.getValue()) continue;
            String permission = permissionInfo.getPermission().toLowerCase();
            if (!permission.startsWith(TOUCH_PERMISSION_PREFIX)) continue;
            String valuePart = permission.substring(TOUCH_PERMISSION_PREFIX.length());
            try {
                int extra = Integer.parseInt(valuePart);
                if (extra > 0) limit += extra;
            } catch (NumberFormatException ignored) {}
        }
        return Math.max(plugin.getConfigManager().miningDefaultTouchLimit, limit);
    }

    public boolean isBlockBusy(org.bukkit.Location loc) {
        MiningTargetKey key = MiningTargetKey.from(loc);
        if (activeBlockMiners.containsKey(key)) return true;
        if (persistedProgress.containsKey(key)) {
            MiningProgressState state = persistedProgress.get(key);
            if (System.currentTimeMillis() - state.getUpdatedAtMs() < plugin.getConfigManager().miningResumeTimeoutMs) {
                return true;
            }
        }
        for (PlayerHealthMiningTask task : activeHealthTasks.values()) {
            if (task.getBlock().getLocation().equals(loc)) {
                return true;
            }
        }
        return false;
    }

    /**
     * Batalkan task mining di lokasi ini secara langsung.
     */
    public void cancelTaskAt(org.bukkit.Location loc) {
        if (loc == null) return;
        MiningTargetKey key = MiningTargetKey.from(loc);
        UUID miner = activeBlockMiners.get(key);
        if (miner != null) {
            PlayerMiningTask task = activeMiningTasks.get(miner);
            if (task != null) task.cancelTask();
        }
        for (PlayerHealthMiningTask task : activeHealthTasks.values()) {
            if (task.getBlock().getLocation().equals(loc)) {
                task.cancelTask();
                break;
            }
        }
        persistedProgress.remove(key);
        activeBlockMiners.remove(key);
    }

    public void cleanupPlayer(UUID uuid) {
        playerTouchedBlocks.remove(uuid);
        mineConflictMessageCooldown.remove(uuid);
    }
}

package me.allync.blockregen.manager;

import com.sk89q.worldedit.bukkit.BukkitAdapter;
import com.sk89q.worldedit.math.BlockVector3;
import com.sk89q.worldguard.WorldGuard;
import com.sk89q.worldguard.protection.managers.RegionManager;
import com.sk89q.worldguard.protection.regions.ProtectedRegion;
import me.allync.blockregen.BlockRegen;
import me.allync.blockregen.data.AutoScanPoint;
import me.allync.blockregen.data.BlockData;
import me.allync.blockregen.util.ModelEngineUtil;
import me.allync.blockregen.util.NexoUtil;
import org.bukkit.Bukkit;
import org.bukkit.Location;
import org.bukkit.Material;
import org.bukkit.World;
import org.bukkit.configuration.ConfigurationSection;
import org.bukkit.configuration.file.FileConfiguration;
import org.bukkit.configuration.file.YamlConfiguration;

import java.io.File;
import java.io.IOException;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ThreadLocalRandom;
import java.util.logging.Level;

/**
 * Manages the Auto-Scan point system.
 *
 * <p>Auto-Scan allows admins to designate specific block locations that are
 * automatically managed by the plugin. On each cycle, each registered location
 * has a configurable chance to show the real ore block (active/mineable) or a
 * placeholder block (inactive/non-mineable). This creates a dynamic "anti-AFK"
 * mining experience without needing to define region pools.</p>
 *
 * <p>Points are registered via a toggle wand (/br scan wand) or automatically
 * when an admin places a configured regen block while in scan-register mode.</p>
 */
public class AutoScanManager {

    private final BlockRegen plugin;
    private final File dataFile;
    private FileConfiguration dataConfig;

    // Keyed by location string for fast lookup
    private final Map<String, AutoScanPoint> points = new ConcurrentHashMap<>();

    // Config values (loaded from config.yml auto-scan section)
    private boolean enabled;
    private int cycleIntervalSeconds;
    private double defaultActiveChance;   // 0-100, default probability ore is visible each cycle
    private Material defaultPlaceholder;

    public AutoScanManager(BlockRegen plugin) {
        this.plugin = plugin;
        this.dataFile = new File(plugin.getDataFolder(), "auto-scan-points.yml");
    }

    // -------------------------------------------------------------------------
    // Load / Save
    // -------------------------------------------------------------------------

    public void load() {
        // Load settings from config.yml
        FileConfiguration cfg = plugin.getConfig();
        this.enabled              = cfg.getBoolean("auto-scan.enabled", false);
        this.cycleIntervalSeconds = cfg.getInt("auto-scan.cycle-interval-seconds", 30);
        this.defaultActiveChance  = cfg.getDouble("auto-scan.default-active-chance", 50.0);

        String placeholderStr = cfg.getString("auto-scan.default-placeholder", "STONE");
        try {
            this.defaultPlaceholder = Material.valueOf(placeholderStr.toUpperCase());
        } catch (IllegalArgumentException e) {
            plugin.getLogger().warning("[AutoScan] Invalid auto-scan.default-placeholder '" + placeholderStr + "'. Defaulting to STONE.");
            this.defaultPlaceholder = Material.STONE;
        }

        // Load persisted points
        points.clear();
        if (!dataFile.exists()) {
            return;
        }

        this.dataConfig = YamlConfiguration.loadConfiguration(dataFile);
        ConfigurationSection section = dataConfig.getConfigurationSection("points");
        if (section == null) return;

        int loaded = 0;
        for (String key : section.getKeys(false)) {
            ConfigurationSection entry = section.getConfigurationSection(key);
            if (entry == null) continue;

            String worldName     = entry.getString("world");
            int x                = entry.getInt("x");
            int y                = entry.getInt("y");
            int z                = entry.getInt("z");
            String blockId       = entry.getString("block-id");
            String placeholderS  = entry.getString("placeholder", "STONE");
            boolean active       = entry.getBoolean("active", false);

            World world = Bukkit.getWorld(worldName);
            if (world == null) {
                plugin.getLogger().warning("[AutoScan] Skipping point in unknown world '" + worldName + "'.");
                continue;
            }

            Material ph;
            try {
                ph = Material.valueOf(placeholderS.toUpperCase());
            } catch (IllegalArgumentException ex) {
                ph = defaultPlaceholder;
            }

            Location loc = new Location(world, x, y, z);
            AutoScanPoint point = new AutoScanPoint(blockId, loc, ph, active);
            points.put(point.getKey(), point);
            loaded++;
        }

        plugin.getLogger().info("[AutoScan] Loaded " + loaded + " auto-scan points.");
    }

    public void save() {
        if (dataConfig == null) {
            dataConfig = new YamlConfiguration();
        }

        // Wipe the points section and rewrite
        dataConfig.set("points", null);

        int index = 0;
        for (AutoScanPoint point : points.values()) {
            String path = "points." + index;
            dataConfig.set(path + ".world",       point.getLocation().getWorld().getName());
            dataConfig.set(path + ".x",           point.getLocation().getBlockX());
            dataConfig.set(path + ".y",           point.getLocation().getBlockY());
            dataConfig.set(path + ".z",           point.getLocation().getBlockZ());
            dataConfig.set(path + ".block-id",    point.getBlockIdentifier());
            dataConfig.set(path + ".placeholder",  point.getPlaceholder().name());
            dataConfig.set(path + ".active",       point.isActive());
            index++;
        }

        try {
            dataConfig.save(dataFile);
        } catch (IOException e) {
            plugin.getLogger().log(Level.SEVERE, "[AutoScan] Could not save auto-scan-points.yml!", e);
        }
    }

    // -------------------------------------------------------------------------
    // Registration / Toggle
    // -------------------------------------------------------------------------

    /**
     * Toggles a location as an auto-scan point. If the block at the location is
     * a configured regen block, it is registered (or unregistered if already present).
     *
     * @return 1 if added, -1 if removed, 0 if the block is not a regen block.
     */
    public int toggle(Location location) {
        if (location == null || location.getWorld() == null) return 0;

        String key = buildKey(location);

        if (points.containsKey(key)) {
            AutoScanPoint point = points.remove(key);
            // Hapus model jika ada sebelum restore
            if (BlockRegen.modelEngineEnabled) {
                ModelEngineUtil.removeModel(location);
                ModelEngineUtil.restoreHiddenBlock(location);
            }
            restoreOreBlock(point);
            save();
            return -1; // removed
        }

        // Detect what regen block is at this location
        String blockId = plugin.getMiningManager().getBlockIdentifier(location.getBlock());
        if (!plugin.getBlockManager().isRegenBlock(blockId)) {
            return 0; // not a regen block
        }

        BlockData data = plugin.getBlockManager().getBlockData(blockId);
        Material placeholder = (data != null) ? data.getReplacedBlock() : defaultPlaceholder;

        // Start as active (ore visible) so the admin can see it's registered
        AutoScanPoint point = new AutoScanPoint(blockId, location, placeholder, true);
        points.put(key, point);
        save();
        return 1; // added
    }

    // -------------------------------------------------------------------------
    // Cycle Logic
    // -------------------------------------------------------------------------

    /**
     * Runs one full cycle: each point independently rolls its active-chance.
     */
    public void runCycle() {
        if (!enabled || points.isEmpty()) return;

        for (AutoScanPoint point : points.values()) {
            Location loc = point.getLocation();
            if (loc.getWorld() == null) continue;

            // NEW: Skip if block is currently being mined/touched by a player
            if (plugin.getBlockMiningListener() != null && plugin.getBlockMiningListener().isBlockBusy(loc)) {
                continue;
            }

            // Get per-block active chance if configured, otherwise use global default
            double chance = getActiveChance(point.getBlockIdentifier());
            boolean shouldBeActive = ThreadLocalRandom.current().nextDouble(100.0) < chance;

            if (shouldBeActive == point.isActive()) continue; // no change needed

            point.setActive(shouldBeActive);

            if (shouldBeActive) {
                // Place the ore block
                placeOreBlock(point);
                // Spawn model jika block ini punya model engine
                if (BlockRegen.modelEngineEnabled) {
                    spawnModelForBlock(point.getBlockIdentifier(), loc);
                }
            } else {
                // Hapus model dulu sebelum ganti jadi placeholder
                if (BlockRegen.modelEngineEnabled) {
                    ModelEngineUtil.removeModel(loc);
                    ModelEngineUtil.restoreHiddenBlock(loc);
                }
                // Batalkan mining task yang mungkin sedang aktif
                plugin.getMiningManager().cancelMiningAt(loc);
                loc.getBlock().setType(point.getPlaceholder(), false);
            }
        }

        save();
    }

    /**
     * Forces a specific point to cycle immediately (debug/admin use).
     */
    public boolean forceCyclePoint(Location location) {
        String key = buildKey(location);
        AutoScanPoint point = points.get(key);
        if (point == null) return false;

        boolean nowActive = !point.isActive();
        point.setActive(nowActive);
        if (nowActive) {
            placeOreBlock(point);
            if (BlockRegen.modelEngineEnabled) {
                spawnModelForBlock(point.getBlockIdentifier(), location);
            }
        } else {
            if (BlockRegen.modelEngineEnabled) {
                ModelEngineUtil.removeModel(location);
                ModelEngineUtil.restoreHiddenBlock(location);
            }
            point.getLocation().getBlock().setType(point.getPlaceholder(), false);
        }
        save();
        return true;
    }

    // -------------------------------------------------------------------------
    // Query helpers
    // -------------------------------------------------------------------------

    public boolean isEnabled() {
        return enabled;
    }

    public int getCycleIntervalSeconds() {
        return cycleIntervalSeconds;
    }

    /**
     * Returns true if the given location is a registered auto-scan point AND it
     * is currently in the inactive (placeholder) state. Used by BlockBreakListener
     * to prevent breaking the placeholder block.
     */
    public boolean isInactivePoint(Location location) {
        if (location == null) return false;
        AutoScanPoint point = points.get(buildKey(location));
        return point != null && !point.isActive();
    }

    /**
     * Returns true if the location is a registered auto-scan point (active or inactive).
     */
    public boolean isRegisteredPoint(Location location) {
        if (location == null) return false;
        return points.containsKey(buildKey(location));
    }

    public int getPointCount() {
        return points.size();
    }

    public Collection<AutoScanPoint> getAllPoints() {
        return Collections.unmodifiableCollection(points.values());
    }

    // -------------------------------------------------------------------------
    // Internal helpers
    // -------------------------------------------------------------------------

    private double getActiveChance(String blockIdentifier) {
        // Per-block chance can be set in blocks.yml under auto-scan.active-chance
        BlockData data = plugin.getBlockManager().getBlockData(blockIdentifier);
        if (data != null && data.getAutoScanActiveChance() >= 0) {
            return data.getAutoScanActiveChance();
        }
        return defaultActiveChance;
    }

    private void placeOreBlock(AutoScanPoint point) {
        Location loc = point.getLocation();
        String blockId = point.getBlockIdentifier();

        if (blockId.toLowerCase().startsWith("nexo:") && BlockRegen.nexoEnabled) {
            NexoUtil.placeNexoBlock(blockId, loc);
            return;
        }

        // ItemsAdder blocks would need special placement — for now fall back to vanilla
        if (blockId.contains(":")) {
            // Custom block without dedicated placement support: skip silently
            plugin.getLogger().warning("[AutoScan] Cannot place custom block '" + blockId + "' — only Nexo blocks support auto-placement. Keeping placeholder.");
            return;
        }

        try {
            Material mat = Material.valueOf(blockId.toUpperCase());
            loc.getBlock().setType(mat, false);
        } catch (IllegalArgumentException e) {
            plugin.getLogger().warning("[AutoScan] Unknown material '" + blockId + "' for auto-scan point. Skipping.");
        }
    }

    private void restoreOreBlock(AutoScanPoint point) {
        // When a point is unregistered, restore it to the ore state
        placeOreBlock(point);
    }

    /**
     * Spawn model untuk blok di lokasi, jika block tersebut punya konfigurasi Model Engine.
     * Hanya dipanggil jika ModelEngine aktif.
     */
    private void spawnModelForBlock(String blockIdentifier, Location location) {
        BlockData data = plugin.getBlockManager().getBlockData(blockIdentifier);
        if (data == null || !data.hasModelEngine()) return;
        ModelEngineUtil.spawnModel(
                location,
                data.getModelEngineId(),
                data.getModelYaw(),
                data.getModelHeightOffset(),
                data.isModelHideBlock()
        );
    }

    // -------------------------------------------------------------------------
    // Region Scan
    // -------------------------------------------------------------------------

    /**
     * Result object returned by {@link #scanRegion(me.allync.blockregen.data.Region)}.
     */
    public static class ScanResult {
        public final int added;
        public final int skipped;   // already registered
        public final int total;     // total regen blocks found

        public ScanResult(int added, int skipped, int total) {
            this.added   = added;
            this.skipped = skipped;
            this.total   = total;
        }
    }

    /**
     * Scans every block inside a BlockRegen internal {@code region} and registers any
     * configured regen block that is not already an auto-scan point.
     *
     * @param region the BlockRegen {@link me.allync.blockregen.data.Region} to scan.
     * @return a {@link ScanResult} describing how many blocks were found/added/skipped.
     */
    public ScanResult scanRegion(me.allync.blockregen.data.Region region) {
        World world = region.getWorld();
        if (world == null) return new ScanResult(0, 0, 0);
        Location min = region.getMinPoint();
        Location max = region.getMaxPoint();
        return scanBoundingBox(world,
                min.getBlockX(), min.getBlockY(), min.getBlockZ(),
                max.getBlockX(), max.getBlockY(), max.getBlockZ());
    }

    /**
     * Scans every block inside a WorldGuard region (by name) across all loaded worlds.
     * Falls back gracefully when WorldGuard is disabled.
     *
     * @param regionName the WorldGuard region ID (case-insensitive).
     * @return a {@link ScanResult}, or {@code null} if the WG region was not found in any world.
     */
    public ScanResult scanWorldGuardRegion(String regionName) {
        if (!plugin.getConfigManager().worldGuardEnabled || plugin.getWorldGuardPlugin() == null) {
            return null;
        }
        for (World world : Bukkit.getWorlds()) {
            try {
                RegionManager wgRM = WorldGuard.getInstance()
                        .getPlatform()
                        .getRegionContainer()
                        .get(BukkitAdapter.adapt(world));
                if (wgRM == null) continue;

                ProtectedRegion pr = wgRM.getRegion(regionName.toLowerCase());
                if (pr == null) continue;

                BlockVector3 min = pr.getMinimumPoint();
                BlockVector3 max = pr.getMaximumPoint();
                return scanBoundingBox(world,
                        min.x(), min.y(), min.z(),
                        max.x(), max.y(), max.z());
            } catch (Exception ignored) {
                // Keep iterating other worlds if one fails
            }
        }
        return null; // not found in any world
    }

    /**
     * Core implementation: iterates every block in the given axis-aligned bounding box
     * and registers any configured regen block not already tracked.
     */
    private ScanResult scanBoundingBox(World world,
                                       int minX, int minY, int minZ,
                                       int maxX, int maxY, int maxZ) {
        int added   = 0;
        int skipped = 0;
        int total   = 0;

        for (int x = minX; x <= maxX; x++) {
            for (int y = minY; y <= maxY; y++) {
                for (int z = minZ; z <= maxZ; z++) {
                    org.bukkit.block.Block block = world.getBlockAt(x, y, z);

                    String blockId = plugin.getMiningManager().getBlockIdentifier(block);
                    if (!plugin.getBlockManager().isRegenBlock(blockId)) continue;

                    total++;
                    Location loc = block.getLocation();
                    String key = buildKey(loc);

                    if (points.containsKey(key)) {
                        skipped++;
                        continue;
                    }

                    BlockData data = plugin.getBlockManager().getBlockData(blockId);
                    Material placeholder = (data != null) ? data.getReplacedBlock() : defaultPlaceholder;

                    AutoScanPoint point = new AutoScanPoint(blockId, loc, placeholder, true);
                    points.put(key, point);
                    added++;
                }
            }
        }

        if (added > 0) {
            save();
        }

        return new ScanResult(added, skipped, total);
    }

    private String buildKey(Location loc) {
        return loc.getWorld().getName()
                + ":" + loc.getBlockX()
                + ":" + loc.getBlockY()
                + ":" + loc.getBlockZ();
    }
}

package me.allync.blockregen.manager;

import com.sk89q.worldedit.bukkit.BukkitAdapter;
import com.sk89q.worldedit.math.BlockVector3;
import com.sk89q.worldguard.WorldGuard;
import com.sk89q.worldguard.protection.managers.RegionManager;
import com.sk89q.worldguard.protection.regions.ProtectedRegion;
import me.allync.blockregen.BlockRegen;
import me.allync.blockregen.data.AutoScanPoint;
import me.allync.blockregen.data.BlockData;
import me.allync.blockregen.util.ModelEngineUtil;
import me.allync.blockregen.util.NexoUtil;
import org.bukkit.Bukkit;
import org.bukkit.Location;
import org.bukkit.Material;
import org.bukkit.World;
import org.bukkit.configuration.ConfigurationSection;
import org.bukkit.configuration.file.FileConfiguration;
import org.bukkit.configuration.file.YamlConfiguration;

import java.io.File;
import java.io.IOException;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ThreadLocalRandom;
import java.util.logging.Level;

/**
 * Manages the Auto-Scan point system.
 *
 * <p>Auto-Scan allows admins to designate specific block locations that are
 * automatically managed by the plugin. On each cycle, each registered location
 * has a configurable chance to show the real ore block (active/mineable) or a
 * placeholder block (inactive/non-mineable). This creates a dynamic "anti-AFK"
 * mining experience without needing to define region pools.</p>
 *
 * <p>Points are registered via a toggle wand (/br scan wand) or automatically
 * when an admin places a configured regen block while in scan-register mode.</p>
 */
public class AutoScanManager {

    private final BlockRegen plugin;
    private final File dataFile;
    private FileConfiguration dataConfig;

    // Keyed by location string for fast lookup
    private final Map<String, AutoScanPoint> points = new ConcurrentHashMap<>();

    // Config values (loaded from config.yml auto-scan section)
    private boolean enabled;
    private int cycleIntervalSeconds;
    private double defaultActiveChance;   // 0-100, default probability ore is visible each cycle
    private Material defaultPlaceholder;

    public AutoScanManager(BlockRegen plugin) {
        this.plugin = plugin;
        this.dataFile = new File(plugin.getDataFolder(), "auto-scan-points.yml");
    }

    // -------------------------------------------------------------------------
    // Load / Save
    // -------------------------------------------------------------------------

    public void load() {
        // Load settings from config.yml
        FileConfiguration cfg = plugin.getConfig();
        this.enabled              = cfg.getBoolean("auto-scan.enabled", false);
        this.cycleIntervalSeconds = cfg.getInt("auto-scan.cycle-interval-seconds", 30);
        this.defaultActiveChance  = cfg.getDouble("auto-scan.default-active-chance", 50.0);

        String placeholderStr = cfg.getString("auto-scan.default-placeholder", "STONE");
        try {
            this.defaultPlaceholder = Material.valueOf(placeholderStr.toUpperCase());
        } catch (IllegalArgumentException e) {
            plugin.getLogger().warning("[AutoScan] Invalid auto-scan.default-placeholder '" + placeholderStr + "'. Defaulting to STONE.");
            this.defaultPlaceholder = Material.STONE;
        }

        // Load persisted points
        points.clear();
        if (!dataFile.exists()) {
            return;
        }

        this.dataConfig = YamlConfiguration.loadConfiguration(dataFile);
        ConfigurationSection section = dataConfig.getConfigurationSection("points");
        if (section == null) return;

        int loaded = 0;
        for (String key : section.getKeys(false)) {
            ConfigurationSection entry = section.getConfigurationSection(key);
            if (entry == null) continue;

            String worldName     = entry.getString("world");
            int x                = entry.getInt("x");
            int y                = entry.getInt("y");
            int z                = entry.getInt("z");
            String blockId       = entry.getString("block-id");
            String placeholderS  = entry.getString("placeholder", "STONE");
            boolean active       = entry.getBoolean("active", false);

            World world = Bukkit.getWorld(worldName);
            if (world == null) {
                plugin.getLogger().warning("[AutoScan] Skipping point in unknown world '" + worldName + "'.");
                continue;
            }

            Material ph;
            try {
                ph = Material.valueOf(placeholderS.toUpperCase());
            } catch (IllegalArgumentException ex) {
                ph = defaultPlaceholder;
            }

            Location loc = new Location(world, x, y, z);
            AutoScanPoint point = new AutoScanPoint(blockId, loc, ph, active);
            points.put(point.getKey(), point);
            loaded++;
        }

        plugin.getLogger().info("[AutoScan] Loaded " + loaded + " auto-scan points.");
    }

    public void save() {
        if (dataConfig == null) {
            dataConfig = new YamlConfiguration();
        }

        // Wipe the points section and rewrite
        dataConfig.set("points", null);

        int index = 0;
        for (AutoScanPoint point : points.values()) {
            String path = "points." + index;
            dataConfig.set(path + ".world",       point.getLocation().getWorld().getName());
            dataConfig.set(path + ".x",           point.getLocation().getBlockX());
            dataConfig.set(path + ".y",           point.getLocation().getBlockY());
            dataConfig.set(path + ".z",           point.getLocation().getBlockZ());
            dataConfig.set(path + ".block-id",    point.getBlockIdentifier());
            dataConfig.set(path + ".placeholder",  point.getPlaceholder().name());
            dataConfig.set(path + ".active",       point.isActive());
            index++;
        }

        try {
            dataConfig.save(dataFile);
        } catch (IOException e) {
            plugin.getLogger().log(Level.SEVERE, "[AutoScan] Could not save auto-scan-points.yml!", e);
        }
    }

    // -------------------------------------------------------------------------
    // Registration / Toggle
    // -------------------------------------------------------------------------

    /**
     * Toggles a location as an auto-scan point. If the block at the location is
     * a configured regen block, it is registered (or unregistered if already present).
     *
     * @return 1 if added, -1 if removed, 0 if the block is not a regen block.
     */
    public int toggle(Location location) {
        if (location == null || location.getWorld() == null) return 0;

        String key = buildKey(location);

        if (points.containsKey(key)) {
            AutoScanPoint point = points.remove(key);
            // Hapus model jika ada sebelum restore
            if (BlockRegen.modelEngineEnabled) {
                ModelEngineUtil.removeModel(location);
                ModelEngineUtil.restoreHiddenBlock(location);
            }
            restoreOreBlock(point);
            save();
            return -1; // removed
        }

        // Detect what regen block is at this location (region-aware)
        java.util.Set<String> regionNames = plugin.getRegionManager().getRegionNamesAt(location);
        String blockId = plugin.getMiningManager().getBlockIdentifier(location.getBlock(), regionNames);
        if (!plugin.getBlockManager().isRegenBlock(blockId)) {
            return 0; // not a regen block
        }

        BlockData data = plugin.getBlockManager().getBlockData(blockId);
        Material placeholder = (data != null) ? data.getReplacedBlock() : defaultPlaceholder;

        // Start as active (ore visible) so the admin can see it's registered
        AutoScanPoint point = new AutoScanPoint(blockId, location, placeholder, true);
        points.put(key, point);
        save();
        return 1; // added
    }

    // -------------------------------------------------------------------------
    // Cycle Logic
    // -------------------------------------------------------------------------

    /**
     * Runs one full cycle: each point independently rolls its active-chance.
     */
    public void runCycle() {
        if (!enabled || points.isEmpty()) return;

        for (AutoScanPoint point : points.values()) {
            Location loc = point.getLocation();
            if (loc.getWorld() == null) continue;

            // NEW: Skip if block is currently being mined/touched by a player
            if (plugin.getBlockMiningListener() != null && plugin.getBlockMiningListener().isBlockBusy(loc)) {
                continue;
            }

            // Get per-block active chance if configured, otherwise use global default
            double chance = getActiveChance(point.getBlockIdentifier());
            boolean shouldBeActive = ThreadLocalRandom.current().nextDouble(100.0) < chance;

            if (shouldBeActive == point.isActive()) continue; // no change needed

            point.setActive(shouldBeActive);

            if (shouldBeActive) {
                // Place the ore block
                placeOreBlock(point);
                // Spawn model jika block ini punya model engine
                if (BlockRegen.modelEngineEnabled) {
                    spawnModelForBlock(point.getBlockIdentifier(), loc);
                }
            } else {
                // Hapus model dulu sebelum ganti jadi placeholder
                if (BlockRegen.modelEngineEnabled) {
                    ModelEngineUtil.removeModel(loc);
                    ModelEngineUtil.restoreHiddenBlock(loc);
                }
                // Batalkan mining task yang mungkin sedang aktif
                plugin.getMiningManager().cancelMiningAt(loc);
                loc.getBlock().setType(point.getPlaceholder(), false);
            }
        }

        save();
    }

    /**
     * Forces a specific point to cycle immediately (debug/admin use).
     */
    public boolean forceCyclePoint(Location location) {
        String key = buildKey(location);
        AutoScanPoint point = points.get(key);
        if (point == null) return false;

        boolean nowActive = !point.isActive();
        point.setActive(nowActive);
        if (nowActive) {
            placeOreBlock(point);
            if (BlockRegen.modelEngineEnabled) {
                spawnModelForBlock(point.getBlockIdentifier(), location);
            }
        } else {
            if (BlockRegen.modelEngineEnabled) {
                ModelEngineUtil.removeModel(location);
                ModelEngineUtil.restoreHiddenBlock(location);
            }
            point.getLocation().getBlock().setType(point.getPlaceholder(), false);
        }
        save();
        return true;
    }

    // -------------------------------------------------------------------------
    // Query helpers
    // -------------------------------------------------------------------------

    public boolean isEnabled() {
        return enabled;
    }

    public int getCycleIntervalSeconds() {
        return cycleIntervalSeconds;
    }

    /**
     * Returns true if the given location is a registered auto-scan point AND it
     * is currently in the inactive (placeholder) state. Used by BlockBreakListener
     * to prevent breaking the placeholder block.
     */
    public boolean isInactivePoint(Location location) {
        if (location == null) return false;
        AutoScanPoint point = points.get(buildKey(location));
        return point != null && !point.isActive();
    }

    /**
     * Returns true if the location is a registered auto-scan point (active or inactive).
     */
    public boolean isRegisteredPoint(Location location) {
        if (location == null) return false;
        return points.containsKey(buildKey(location));
    }

    public int getPointCount() {
        return points.size();
    }

    public Collection<AutoScanPoint> getAllPoints() {
        return Collections.unmodifiableCollection(points.values());
    }

    // -------------------------------------------------------------------------
    // Internal helpers
    // -------------------------------------------------------------------------

    private double getActiveChance(String blockIdentifier) {
        // Per-block chance can be set in blocks.yml under auto-scan.active-chance
        BlockData data = plugin.getBlockManager().getBlockData(blockIdentifier);
        if (data != null && data.getAutoScanActiveChance() >= 0) {
            return data.getAutoScanActiveChance();
        }
        return defaultActiveChance;
    }

    private void placeOreBlock(AutoScanPoint point) {
        Location loc = point.getLocation();
        String blockId = point.getBlockIdentifier();

        if (blockId.toLowerCase().startsWith("nexo:") && BlockRegen.nexoEnabled) {
            NexoUtil.placeNexoBlock(blockId, loc);
            return;
        }

        // ItemsAdder blocks would need special placement — for now fall back to vanilla
        if (blockId.contains(":")) {
            // Custom block without dedicated placement support: skip silently
            plugin.getLogger().warning("[AutoScan] Cannot place custom block '" + blockId + "' — only Nexo blocks support auto-placement. Keeping placeholder.");
            return;
        }

        try {
            Material mat = Material.valueOf(blockId.toUpperCase());
            loc.getBlock().setType(mat, false);
        } catch (IllegalArgumentException e) {
            plugin.getLogger().warning("[AutoScan] Unknown material '" + blockId + "' for auto-scan point. Skipping.");
        }
    }

    private void restoreOreBlock(AutoScanPoint point) {
        // When a point is unregistered, restore it to the ore state
        placeOreBlock(point);
    }

    /**
     * Spawn model untuk blok di lokasi, jika block tersebut punya konfigurasi Model Engine.
     * Hanya dipanggil jika ModelEngine aktif.
     */
    private void spawnModelForBlock(String blockIdentifier, Location location) {
        BlockData data = plugin.getBlockManager().getBlockData(blockIdentifier);
        if (data == null || !data.hasModelEngine()) return;
        ModelEngineUtil.spawnModel(
                location,
                data.getModelEngineId(),
                data.getModelYaw(),
                data.getModelHeightOffset(),
                data.isModelHideBlock()
        );
    }

    // -------------------------------------------------------------------------
    // Region Scan
    // -------------------------------------------------------------------------

    /**
     * Result object returned by {@link #scanRegion(me.allync.blockregen.data.Region)}.
     */
    public static class ScanResult {
        public final int added;
        public final int skipped;   // already registered
        public final int total;     // total regen blocks found

        public ScanResult(int added, int skipped, int total) {
            this.added   = added;
            this.skipped = skipped;
            this.total   = total;
        }
    }

    /**
     * Scans every block inside a BlockRegen internal {@code region} and registers any
     * configured regen block that is not already an auto-scan point.
     *
     * @param region the BlockRegen {@link me.allync.blockregen.data.Region} to scan.
     * @return a {@link ScanResult} describing how many blocks were found/added/skipped.
     */
    public ScanResult scanRegion(me.allync.blockregen.data.Region region) {
        World world = region.getWorld();
        if (world == null) return new ScanResult(0, 0, 0);
        Location min = region.getMinPoint();
        Location max = region.getMaxPoint();
        return scanBoundingBox(world,
                min.getBlockX(), min.getBlockY(), min.getBlockZ(),
                max.getBlockX(), max.getBlockY(), max.getBlockZ());
    }

    /**
     * Scans every block inside a WorldGuard region (by name) across all loaded worlds.
     * Falls back gracefully when WorldGuard is disabled.
     *
     * @param regionName the WorldGuard region ID (case-insensitive).
     * @return a {@link ScanResult}, or {@code null} if the WG region was not found in any world.
     */
    public ScanResult scanWorldGuardRegion(String regionName) {
        if (!plugin.getConfigManager().worldGuardEnabled || plugin.getWorldGuardPlugin() == null) {
            return null;
        }
        for (World world : Bukkit.getWorlds()) {
            try {
                RegionManager wgRM = WorldGuard.getInstance()
                        .getPlatform()
                        .getRegionContainer()
                        .get(BukkitAdapter.adapt(world));
                if (wgRM == null) continue;

                ProtectedRegion pr = wgRM.getRegion(regionName.toLowerCase());
                if (pr == null) continue;

                BlockVector3 min = pr.getMinimumPoint();
                BlockVector3 max = pr.getMaximumPoint();
                return scanBoundingBox(world,
                        min.x(), min.y(), min.z(),
                        max.x(), max.y(), max.z());
            } catch (Exception ignored) {
                // Keep iterating other worlds if one fails
            }
        }
        return null; // not found in any world
    }

    /**
     * Core implementation: iterates every block in the given axis-aligned bounding box
     * and registers any configured regen block not already tracked.
     */
    private ScanResult scanBoundingBox(World world,
                                       int minX, int minY, int minZ,
                                       int maxX, int maxY, int maxZ) {
        int added   = 0;
        int skipped = 0;
        int total   = 0;

        for (int x = minX; x <= maxX; x++) {
            for (int y = minY; y <= maxY; y++) {
                for (int z = minZ; z <= maxZ; z++) {
                    org.bukkit.block.Block block = world.getBlockAt(x, y, z);

                    java.util.Set<String> regionNames = plugin.getRegionManager().getRegionNamesAt(block.getLocation());
                    String blockId = plugin.getMiningManager().getBlockIdentifier(block, regionNames);
                    if (!plugin.getBlockManager().isRegenBlock(blockId)) continue;

                    total++;
                    Location loc = block.getLocation();
                    String key = buildKey(loc);

                    if (points.containsKey(key)) {
                        skipped++;
                        continue;
                    }

                    BlockData data = plugin.getBlockManager().getBlockData(blockId);
                    Material placeholder = (data != null) ? data.getReplacedBlock() : defaultPlaceholder;

                    AutoScanPoint point = new AutoScanPoint(blockId, loc, placeholder, true);
                    points.put(key, point);
                    added++;
                }
            }
        }

        if (added > 0) {
            save();
        }

        return new ScanResult(added, skipped, total);
    }

    private String buildKey(Location loc) {
        return loc.getWorld().getName()
                + ":" + loc.getBlockX()
                + ":" + loc.getBlockY()
                + ":" + loc.getBlockZ();
    }
}

package me.allync.blockregen.manager;

import dev.lone.itemsadder.api.CustomBlock;
import me.allync.blockregen.BlockRegen;
import me.allync.blockregen.data.BlockData;
import me.allync.blockregen.util.NexoUtil;
import org.bukkit.Material;
import org.bukkit.block.Block;
import org.bukkit.configuration.ConfigurationSection;
import org.bukkit.configuration.file.FileConfiguration;
import org.bukkit.configuration.file.YamlConfiguration;

import java.io.File;
import java.util.Collection;
import java.util.HashMap;
import java.util.Map;
import java.util.HashSet;
import java.util.Set;
import java.util.Locale;
import java.util.logging.Level;

public class BlockManager {

    private final BlockRegen plugin;
    // Changed the map key from Material to String to support ItemsAdder IDs
    private final Map<String, BlockData> blockDataMap = new HashMap<>();
    // Reverse mapping: vanilla block names (STONE, IRON_ORE, etc) → BlockData
    // This allows fallback lookup for blocks specified in regen-blocks section
    private final Map<String, BlockData> regenBlockMap = new HashMap<>();

    public BlockManager(BlockRegen plugin) {
        this.plugin = plugin;
    }

    public void loadBlocks() {
        blockDataMap.clear();
        regenBlockMap.clear();

        File blocksFolder = new File(plugin.getDataFolder(), "blocks");
        File legacyFile   = new File(plugin.getDataFolder(), "blocks/blocks.yml");

        // ── Migrasi otomatis: jika folder belum ada tapi blocks.yml ada,
        //    pindahkan blocks.yml ke dalam folder sebagai example.yml ────────
        if (!blocksFolder.exists() && legacyFile.exists()) {
            blocksFolder.mkdirs();
            File dest = new File(blocksFolder, "example.yml");
            if (legacyFile.renameTo(dest)) {
                plugin.getLogger().info("Migrated blocks.yml → blocks/example.yml");
            }
        }

        // ── Jika folder belum ada (fresh install), buat + copy resource ────
        if (!blocksFolder.exists()) {
            blocksFolder.mkdirs();
            copyDefaultBlockFile("blocks/vanilla.yml", blocksFolder, "vanilla.yml");
            copyDefaultBlockFile("blocks/custom.yml",  blocksFolder, "custom.yml");
        }

        // ── Baca semua .yml di dalam folder blocks/ (non-recursive) ─────────
        File[] ymlFiles = blocksFolder.listFiles(f -> f.isFile() && f.getName().endsWith(".yml"));
        if (ymlFiles == null || ymlFiles.length == 0) {
            plugin.getLogger().warning("No .yml files found in blocks/ folder!");
            return;
        }

        int totalLoaded = 0;
        for (File ymlFile : ymlFiles) {
            int count = loadFromFile(ymlFile);
            totalLoaded += count;
            plugin.getLogger().info("  └─ " + ymlFile.getName() + " → " + count + " block(s)");
        }
        plugin.getLogger().info("Loaded " + totalLoaded + " block configuration(s) from " + ymlFiles.length + " file(s) in blocks/.");
    }

    /**
     * Memuat semua konfigurasi blok dari satu file .yml.
     *
     * @param file File YAML yang akan dibaca
     * @return Jumlah blok yang berhasil di-load dari file ini
     */
    private int loadFromFile(File file) {
        FileConfiguration cfg;
        try {
            cfg = YamlConfiguration.loadConfiguration(file);
        } catch (Exception e) {
            plugin.getLogger().log(Level.SEVERE, "Failed to parse " + file.getName(), e);
            return 0;
        }

        int count = 0;
        for (String key : cfg.getKeys(false)) {
            ConfigurationSection section = cfg.getConfigurationSection(key);
            if (section == null) continue;
            try {
                BlockData data = new BlockData(section);
                String normalizedKey = normalizeIdentifier(key);
                if (blockDataMap.containsKey(normalizedKey)) {
                    plugin.getLogger().warning("Duplicate block key '" + key + "' in " + file.getName() + " — overwriting previous entry.");
                }
                blockDataMap.put(normalizedKey, data);

                // --- BUILD REVERSE MAPPING: vanilla block names from regen-blocks → BlockData ---
                // This allows pure vanilla blocks (without custom config ID) to still be matched
                if (data.hasRegenVariants()) {
                    for (BlockData.RegenVariant variant : data.getRegenVariants()) {
                        String variantId = variant.getBlockIdentifier();
                        if (variantId != null && !variantId.isEmpty()) {
                            String normalizedVariant = normalizeIdentifier(variantId);
                            // Only add if it's a vanilla material name (not a custom namespace)
                            if (!variantId.contains(":") && !variantId.toLowerCase().startsWith("nexo:")) {
                                try {
                                    // Verify it's a valid vanilla material
                                    Material.valueOf(variantId.toUpperCase(Locale.ROOT));
                                    // Store mapping: vanilla name → original BlockData
                                    // This mapping helps when vanilla blocks are broken and need to be looked up by config
                                    if (!regenBlockMap.containsKey(normalizedVariant)) {
                                        regenBlockMap.put(normalizedVariant, data);
                                    }
                                } catch (IllegalArgumentException ignored) {
                                    // Not a vanilla material, skip
                                }
                            }
                        }
                    }
                }
                // --- END BUILD REVERSE MAPPING ---

                count++;
            } catch (Exception e) {
                plugin.getLogger().log(Level.SEVERE, "Failed to load block '" + key + "' in " + file.getName(), e);
            }
        }
        return count;
    }

    /** Meng-copy file resource bawaan ke dalam folder blocks/ saat fresh install. */
    private void copyDefaultBlockFile(String resourcePath, File targetFolder, String targetName) {
        File dest = new File(targetFolder, targetName);
        if (dest.exists()) return;
        try (java.io.InputStream in = plugin.getResource(resourcePath)) {
            if (in != null) {
                java.nio.file.Files.copy(in, dest.toPath());
                plugin.getLogger().info("Created blocks/" + targetName + " (default).");
            }
        } catch (Exception e) {
            plugin.getLogger().warning("Could not write blocks/" + targetName + ": " + e.getMessage());
        }
    }

    /**
     * Gets the BlockData for a given identifier.
     * @param identifier The block identifier (e.g., "DIAMOND_ORE" or "itemsadder:ruby_ore").
     * @return The BlockData, or null if not found.
     */
    public BlockData getBlockData(String identifier) {
        if (identifier == null) return null;
        String normalizedKey = normalizeIdentifier(identifier);
        return blockDataMap.get(normalizedKey);
    }

    public BlockData getBlockData(Block block) {
        if (block == null) {
            return null;
        }

        //  First try direct match against configured blocks
        for (BlockData data : blockDataMap.values()) {
            if (matchesConfiguredBlock(data, block)) {
                return data;
            }
        }

        // Fallback: try to match against vanilla block names in regenBlockMap
        // This handles cases where a pure vanilla block (not specifically configured)
        // is broken but appears in some config's regen-blocks section
        String materialName = normalizeIdentifier(block.getType().name());
        BlockData fallbackData = regenBlockMap.get(materialName);
        if (fallbackData != null) {
            return fallbackData;
        }

        return null;
    }

    /**
     * Gets the configured identifier for a block with region context.
     * This is needed to pick the correct BlockData when multiple floors have the same block type.
     * @param block The block
     * @param regionNames The regions the block is in (for context-aware matching)
     * @return The configured identifier or vanilla block name
     */
    public String getConfiguredIdentifier(Block block, Collection<String> regionNames) {
        if (block == null) {
            return null;
        }

        // First try: direct match with region context
        for (Map.Entry<String, BlockData> entry : blockDataMap.entrySet()) {
            BlockData data = entry.getValue();
            if (matchesConfiguredBlock(data, block) && data.isRegionAllowed(regionNames)) {
                return data.getConfiguredId();
            }
        }

        // Second try: fallback to vanilla block lookup, but filter by region
        String materialName = normalizeIdentifier(block.getType().name());
        BlockData fallbackData = regenBlockMap.get(materialName);
        if (fallbackData != null && fallbackData.isRegionAllowed(regionNames)) {
            return fallbackData.getConfiguredId();
        }

        // Third try: Nexo blocks
        String nexoId = BlockRegen.nexoEnabled ? NexoUtil.getNexoBlockId(block) : null;
        if (nexoId != null) {
            return nexoId;
        }

        // Fourth try: ItemsAdder blocks
        if (BlockRegen.itemsAdderEnabled) {
            try {
                CustomBlock customBlock = CustomBlock.byAlreadyPlaced(block);
                if (customBlock != null && customBlock.getNamespacedID() != null && !customBlock.getNamespacedID().isEmpty()) {
                    return customBlock.getNamespacedID();
                }
            } catch (Throwable ignored) {
            }
        }

        // Final fallback: vanilla material name
        return block.getType().name();
    }

    public String getConfiguredIdentifier(Block block) {
        BlockData data = getBlockData(block);
        if (data != null) {
            return data.getConfiguredId();
        }

        if (block == null) {
            return null;
        }

        String nexoId = BlockRegen.nexoEnabled ? NexoUtil.getNexoBlockId(block) : null;
        if (nexoId != null) {
            return nexoId;
        }

        if (BlockRegen.itemsAdderEnabled) {
            try {
                CustomBlock customBlock = CustomBlock.byAlreadyPlaced(block);
                if (customBlock != null && customBlock.getNamespacedID() != null && !customBlock.getNamespacedID().isEmpty()) {
                    return customBlock.getNamespacedID();
                }
            } catch (Throwable ignored) {
            }
        }

        return block.getType().name();
    }

    public BlockData getBlockData(String identifier, String regionName) {
        BlockData data = getBlockData(identifier);
        if (data == null) {
            return null;
        }
        return data.isRegionAllowed(regionName) ? data : null;
    }

    public BlockData getBlockData(String identifier, Collection<String> regionNames) {
        BlockData data = getBlockData(identifier);
        if (data == null) {
            return null;
        }
        return data.isRegionAllowed(regionNames) ? data : null;
    }

    /**
     * Checks if a block identifier is a configured regen block.
     * @param identifier The block identifier (e.g., "DIAMOND_ORE" or "itemsadder:ruby_ore").
     * @return True if it is a regen block, false otherwise.
     */
    public boolean isRegenBlock(String identifier) {
        if (identifier == null) return false;
        String normalizedKey = normalizeIdentifier(identifier);
        return blockDataMap.containsKey(normalizedKey);
    }

    public boolean isRegenBlockInRegion(String identifier, String regionName) {
        return getBlockData(identifier, regionName) != null;
    }

    public boolean isRegenBlockInRegion(String identifier, Collection<String> regionNames) {
        return getBlockData(identifier, regionNames) != null;
    }

    public Set<String> getConfiguredIdentifiers() {
        Set<String> identifiers = new HashSet<>();
        for (BlockData data : blockDataMap.values()) {
            if (data != null && data.getConfiguredId() != null && !data.getConfiguredId().isEmpty()) {
                identifiers.add(data.getConfiguredId());
            }
        }
        return identifiers;
    }

    private boolean matchesConfiguredBlock(BlockData data, Block block) {
        if (data == null || block == null) {
            return false;
        }

        String blockId = data.getBlockId();
        if (blockId == null || blockId.isEmpty()) {
            return false;
        }

        String lower = blockId.toLowerCase(Locale.ROOT);
        if (lower.startsWith("nexo:")) {
            String worldId = BlockRegen.nexoEnabled ? NexoUtil.getNexoBlockId(block) : null;
            return worldId != null && worldId.equalsIgnoreCase(blockId);
        }

        if (blockId.contains(":")) {
            try {
                CustomBlock customBlock = CustomBlock.byAlreadyPlaced(block);
                return customBlock != null && blockId.equalsIgnoreCase(customBlock.getNamespacedID());
            } catch (Throwable ignored) {
                return false;
            }
        }

        try {
            Material material = Material.valueOf(blockId.toUpperCase(Locale.ROOT));
            return block.getType() == material;
        } catch (IllegalArgumentException ignored) {
            return false;
        }
    }

    private String normalizeIdentifier(String identifier) {
        return identifier == null ? null : identifier.toLowerCase(Locale.ROOT);
    }
}

package me.allync.blockregen.manager;

import dev.lone.itemsadder.api.CustomBlock;
import me.allync.blockregen.BlockRegen;
import me.allync.blockregen.data.BlockData;
import me.allync.blockregen.util.NexoUtil;
import org.bukkit.Material;
import org.bukkit.block.Block;
import org.bukkit.configuration.ConfigurationSection;
import org.bukkit.configuration.file.FileConfiguration;
import org.bukkit.configuration.file.YamlConfiguration;

import java.io.File;
import java.util.Collection;
import java.util.HashMap;
import java.util.Map;
import java.util.HashSet;
import java.util.Set;
import java.util.Locale;
import java.util.logging.Level;

public class BlockManager {

    private final BlockRegen plugin;
    // Changed the map key from Material to String to support ItemsAdder IDs
    private final Map<String, BlockData> blockDataMap = new HashMap<>();
    // Reverse mapping: vanilla block names (STONE, IRON_ORE, etc) → List<BlockData>
    // Multiple BlockData entries may reference the same vanilla material (e.g. floor1 and floor3 both use IRON_ORE)
    // Store a list so we can perform region-aware disambiguation later.
    private final Map<String, java.util.List<BlockData>> regenBlockMap = new HashMap<>();

    public BlockManager(BlockRegen plugin) {
        this.plugin = plugin;
    }

    public void loadBlocks() {
        blockDataMap.clear();
        regenBlockMap.clear();

        File blocksFolder = new File(plugin.getDataFolder(), "blocks");
        File legacyFile   = new File(plugin.getDataFolder(), "blocks/blocks.yml");

        // ── Migrasi otomatis: jika folder belum ada tapi blocks.yml ada,
        //    pindahkan blocks.yml ke dalam folder sebagai example.yml ────────
        if (!blocksFolder.exists() && legacyFile.exists()) {
            blocksFolder.mkdirs();
            File dest = new File(blocksFolder, "example.yml");
            if (legacyFile.renameTo(dest)) {
                plugin.getLogger().info("Migrated blocks.yml → blocks/example.yml");
            }
        }

        // ── Jika folder belum ada (fresh install), buat + copy resource ────
        if (!blocksFolder.exists()) {
            blocksFolder.mkdirs();
            copyDefaultBlockFile("blocks/vanilla.yml", blocksFolder, "vanilla.yml");
            copyDefaultBlockFile("blocks/custom.yml",  blocksFolder, "custom.yml");
        }

        // ── Baca semua .yml di dalam folder blocks/ (non-recursive) ─────────
        File[] ymlFiles = blocksFolder.listFiles(f -> f.isFile() && f.getName().endsWith(".yml"));
        if (ymlFiles == null || ymlFiles.length == 0) {
            plugin.getLogger().warning("No .yml files found in blocks/ folder!");
            return;
        }

        int totalLoaded = 0;
        for (File ymlFile : ymlFiles) {
            int count = loadFromFile(ymlFile);
            totalLoaded += count;
            plugin.getLogger().info("  └─ " + ymlFile.getName() + " → " + count + " block(s)");
        }
        plugin.getLogger().info("Loaded " + totalLoaded + " block configuration(s) from " + ymlFiles.length + " file(s) in blocks/.");
    }

    /**
     * Memuat semua konfigurasi blok dari satu file .yml.
     *
     * @param file File YAML yang akan dibaca
     * @return Jumlah blok yang berhasil di-load dari file ini
     */
    private int loadFromFile(File file) {
        FileConfiguration cfg;
        try {
            cfg = YamlConfiguration.loadConfiguration(file);
        } catch (Exception e) {
            plugin.getLogger().log(Level.SEVERE, "Failed to parse " + file.getName(), e);
            return 0;
        }

        int count = 0;
        for (String key : cfg.getKeys(false)) {
            ConfigurationSection section = cfg.getConfigurationSection(key);
            if (section == null) continue;
            try {
                BlockData data = new BlockData(section);
                String normalizedKey = normalizeIdentifier(key);
                if (blockDataMap.containsKey(normalizedKey)) {
                    plugin.getLogger().warning("Duplicate block key '" + key + "' in " + file.getName() + " — overwriting previous entry.");
                }
                blockDataMap.put(normalizedKey, data);

                // --- BUILD REVERSE MAPPING: vanilla block names from regen-blocks → BlockData ---
                // This allows pure vanilla blocks (without custom config ID) to still be matched
                if (data.hasRegenVariants()) {
                    for (BlockData.RegenVariant variant : data.getRegenVariants()) {
                        String variantId = variant.getBlockIdentifier();
                        if (variantId != null && !variantId.isEmpty()) {
                            String normalizedVariant = normalizeIdentifier(variantId);
                            // Only add if it's a vanilla material name (not a custom namespace)
                            if (!variantId.contains(":") && !variantId.toLowerCase().startsWith("nexo:")) {
                                try {
                                    // Verify it's a valid vanilla material
                                    Material.valueOf(variantId.toUpperCase(Locale.ROOT));
                                    // Store mapping: vanilla name → list of BlockData that reference it
                                    // Keep insertion order per-file so behavior is deterministic but allow multiple entries
                                    java.util.List<BlockData> list = regenBlockMap.get(normalizedVariant);
                                    if (list == null) {
                                        list = new java.util.ArrayList<>();
                                        regenBlockMap.put(normalizedVariant, list);
                                    }
                                    // Avoid exact duplicates
                                    if (!list.contains(data)) {
                                        list.add(data);
                                    }
                                } catch (IllegalArgumentException ignored) {
                                    // Not a vanilla material, skip
                                }
                            }
                        }
                    }
                }
                // --- END BUILD REVERSE MAPPING ---

                count++;
            } catch (Exception e) {
                plugin.getLogger().log(Level.SEVERE, "Failed to load block '" + key + "' in " + file.getName(), e);
            }
        }
        return count;
    }

    /** Meng-copy file resource bawaan ke dalam folder blocks/ saat fresh install. */
    private void copyDefaultBlockFile(String resourcePath, File targetFolder, String targetName) {
        File dest = new File(targetFolder, targetName);
        if (dest.exists()) return;
        try (java.io.InputStream in = plugin.getResource(resourcePath)) {
            if (in != null) {
                java.nio.file.Files.copy(in, dest.toPath());
                plugin.getLogger().info("Created blocks/" + targetName + " (default).");
            }
        } catch (Exception e) {
            plugin.getLogger().warning("Could not write blocks/" + targetName + ": " + e.getMessage());
        }
    }

    /**
     * Gets the BlockData for a given identifier.
     * @param identifier The block identifier (e.g., "DIAMOND_ORE" or "itemsadder:ruby_ore").
     * @return The BlockData, or null if not found.
     */
    public BlockData getBlockData(String identifier) {
        if (identifier == null) return null;
        String normalizedKey = normalizeIdentifier(identifier);
        return blockDataMap.get(normalizedKey);
    }

    public BlockData getBlockData(Block block) {
        if (block == null) {
            return null;
        }

        java.util.List<BlockData> candidates = new java.util.ArrayList<>();
        for (BlockData data : blockDataMap.values()) {
            if (matchesConfiguredBlock(data, block)) {
                candidates.add(data);
            }
        }

        // If multiple configured BlockData matched the block type, try to pick the best candidate
        if (candidates.size() == 1) {
            return candidates.get(0);
        } else if (candidates.size() > 1) {
            // No region context available here — prefer non-region-specific BlockData, then smallest region set, then deterministic fallback
            candidates.sort((a, b) -> {
                // Prefer entries without region restriction
                if (a.hasRegionRestriction() && !b.hasRegionRestriction()) return 1;
                if (!a.hasRegionRestriction() && b.hasRegionRestriction()) return -1;
                // Prefer smaller allowedRegions (more specific)
                int cmp = Integer.compare(a.getAllowedRegions().size(), b.getAllowedRegions().size());
                if (cmp != 0) return cmp;
                // Deterministic fallback: configured id lexicographic
                return a.getConfiguredId().compareToIgnoreCase(b.getConfiguredId());
            });
            return candidates.get(0);
        }

        // Fallback: try to match against vanilla block names in regenBlockMap
        // This handles cases where a pure vanilla block (not specifically configured)
        // is broken but appears in some config's regen-blocks section
        String materialName = normalizeIdentifier(block.getType().name());
        java.util.List<BlockData> list = regenBlockMap.get(materialName);
        if (list == null || list.isEmpty()) return null;

        // Choose best candidate from list without region context
        list.sort((a, b) -> {
            if (a.hasRegionRestriction() && !b.hasRegionRestriction()) return 1;
            if (!a.hasRegionRestriction() && b.hasRegionRestriction()) return -1;
            int cmp = Integer.compare(a.getAllowedRegions().size(), b.getAllowedRegions().size());
            if (cmp != 0) return cmp;
            return a.getConfiguredId().compareToIgnoreCase(b.getConfiguredId());
        });
        return list.get(0);
    }

    /**
     * Gets the configured identifier for a block with region context.
     * This is needed to pick the correct BlockData when multiple floors have the same block type.
     * @param block The block
     * @param regionNames The regions the block is in (for context-aware matching)
     * @return The configured identifier or vanilla block name
     */
    public String getConfiguredIdentifier(Block block, Collection<String> regionNames) {
        if (block == null) {
            return null;
        }
        // Gather candidates that match the block type
        java.util.List<BlockData> candidates = new java.util.ArrayList<>();
        for (BlockData data : blockDataMap.values()) {
            if (matchesConfiguredBlock(data, block)) {
                candidates.add(data);
            }
        }

        // If direct configured candidates exist, choose the best by region specificity
        BlockData best = chooseBestCandidate(candidates, regionNames);
        if (best != null) return best.getConfiguredId();

        // Second try: fallback to vanilla block lookup, but there may be multiple BlockData referencing this vanilla material
        String materialName = normalizeIdentifier(block.getType().name());
        java.util.List<BlockData> list = regenBlockMap.get(materialName);
        if (list != null && !list.isEmpty()) {
            best = chooseBestCandidate(list, regionNames);
            if (best != null) return best.getConfiguredId();
        }

        // Third try: Nexo blocks
        String nexoId = BlockRegen.nexoEnabled ? NexoUtil.getNexoBlockId(block) : null;
        if (nexoId != null) {
            return nexoId;
        }

        // Fourth try: ItemsAdder blocks
        if (BlockRegen.itemsAdderEnabled) {
            try {
                CustomBlock customBlock = CustomBlock.byAlreadyPlaced(block);
                if (customBlock != null && customBlock.getNamespacedID() != null && !customBlock.getNamespacedID().isEmpty()) {
                    return customBlock.getNamespacedID();
                }
            } catch (Throwable ignored) {
            }
        }

        // Final fallback: vanilla material name
        return block.getType().name();
    }

    public String getConfiguredIdentifier(Block block) {
        BlockData data = getBlockData(block);
        if (data != null) {
            return data.getConfiguredId();
        }

        if (block == null) {
            return null;
        }

        String nexoId = BlockRegen.nexoEnabled ? NexoUtil.getNexoBlockId(block) : null;
        if (nexoId != null) {
            return nexoId;
        }

        if (BlockRegen.itemsAdderEnabled) {
            try {
                CustomBlock customBlock = CustomBlock.byAlreadyPlaced(block);
                if (customBlock != null && customBlock.getNamespacedID() != null && !customBlock.getNamespacedID().isEmpty()) {
                    return customBlock.getNamespacedID();
                }
            } catch (Throwable ignored) {
            }
        }

        return block.getType().name();
    }

    public BlockData getBlockData(String identifier, String regionName) {
        BlockData data = getBlockData(identifier);
        if (data == null) {
            return null;
        }
        return data.isRegionAllowed(regionName) ? data : null;
    }

    public BlockData getBlockData(String identifier, Collection<String> regionNames) {
        BlockData data = getBlockData(identifier);
        if (data == null) {
            return null;
        }
        return data.isRegionAllowed(regionNames) ? data : null;
    }

    /**
     * Checks if a block identifier is a configured regen block.
     * @param identifier The block identifier (e.g., "DIAMOND_ORE" or "itemsadder:ruby_ore").
     * @return True if it is a regen block, false otherwise.
     */
    public boolean isRegenBlock(String identifier) {
        if (identifier == null) return false;
        String normalizedKey = normalizeIdentifier(identifier);
        return blockDataMap.containsKey(normalizedKey);
    }

    public boolean isRegenBlockInRegion(String identifier, String regionName) {
        return getBlockData(identifier, regionName) != null;
    }

    public boolean isRegenBlockInRegion(String identifier, Collection<String> regionNames) {
        return getBlockData(identifier, regionNames) != null;
    }

    public Set<String> getConfiguredIdentifiers() {
        Set<String> identifiers = new HashSet<>();
        for (BlockData data : blockDataMap.values()) {
            if (data != null && data.getConfiguredId() != null && !data.getConfiguredId().isEmpty()) {
                identifiers.add(data.getConfiguredId());
            }
        }
        return identifiers;
    }

    /**
     * Choose the best BlockData candidate from a list given the region context.
     * Scoring rules:
     *  - Prefer candidates with the largest intersection count with provided regionNames
     *  - If intersection counts are equal and > 0, prefer the candidate with smaller allowedRegions (more specific)
     *  - If no candidate matches any region (intersection == 0), prefer non-region-restricted entries
     *  - Deterministic fallback: configuredId lexicographic
     */
    private BlockData chooseBestCandidate(java.util.List<BlockData> candidates, Collection<String> regionNames) {
        if (candidates == null || candidates.isEmpty()) return null;

        // Normalize regionNames to lower-case set for comparisons
        java.util.Set<String> normalized = new java.util.HashSet<>();
        if (regionNames != null) {
            for (String r : regionNames) {
                if (r != null) normalized.add(r.toLowerCase(Locale.ROOT));
            }
        }

        // If there is only one, return it (fast path)
        if (candidates.size() == 1) return candidates.get(0);

        candidates.sort((a, b) -> {
            int aMatch = 0;
            int bMatch = 0;
            if (!normalized.isEmpty()) {
                for (String ar : a.getAllowedRegions()) if (ar != null && normalized.contains(ar.toLowerCase(Locale.ROOT))) aMatch++;
                for (String br : b.getAllowedRegions()) if (br != null && normalized.contains(br.toLowerCase(Locale.ROOT))) bMatch++;
            }
            // Primary: higher match count
            if (aMatch != bMatch) return Integer.compare(bMatch, aMatch);

            // If none matched any region, prefer non-restricted entries
            if (aMatch == 0 && bMatch == 0) {
                if (a.hasRegionRestriction() && !b.hasRegionRestriction()) return 1;
                if (!a.hasRegionRestriction() && b.hasRegionRestriction()) return -1;
            }

            // Secondary: smaller allowedRegions (more specific)
            int cmp = Integer.compare(a.getAllowedRegions().size(), b.getAllowedRegions().size());
            if (cmp != 0) return cmp;

            // Final deterministic fallback
            return a.getConfiguredId().compareToIgnoreCase(b.getConfiguredId());
        });

        return candidates.get(0);
    }

    private boolean matchesConfiguredBlock(BlockData data, Block block) {
        if (data == null || block == null) {
            return false;
        }

        String blockId = data.getBlockId();
        if (blockId == null || blockId.isEmpty()) {
            return false;
        }

        String lower = blockId.toLowerCase(Locale.ROOT);
        if (lower.startsWith("nexo:")) {
            String worldId = BlockRegen.nexoEnabled ? NexoUtil.getNexoBlockId(block) : null;
            return worldId != null && worldId.equalsIgnoreCase(blockId);
        }

        if (blockId.contains(":")) {
            try {
                CustomBlock customBlock = CustomBlock.byAlreadyPlaced(block);
                return customBlock != null && blockId.equalsIgnoreCase(customBlock.getNamespacedID());
            } catch (Throwable ignored) {
                return false;
            }
        }

        try {
            Material material = Material.valueOf(blockId.toUpperCase(Locale.ROOT));
            return block.getType() == material;
        } catch (IllegalArgumentException ignored) {
            return false;
        }
    }

    private String normalizeIdentifier(String identifier) {
        return identifier == null ? null : identifier.toLowerCase(Locale.ROOT);
    }
}

package me.allync.blockregen.manager;

import dev.lone.itemsadder.api.CustomBlock;
import me.allync.blockregen.BlockRegen;
import me.allync.blockregen.data.BlockData;
import me.allync.blockregen.util.ModelEngineUtil;
import me.allync.blockregen.util.NexoUtil;
import org.bukkit.Bukkit;
import org.bukkit.Location;
import org.bukkit.Material;
import org.bukkit.World;
import org.bukkit.configuration.ConfigurationSection;
import org.bukkit.configuration.file.FileConfiguration;
import org.bukkit.configuration.file.YamlConfiguration;

import java.io.File;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ThreadLocalRandom;

public class RandomOreManager {

    private static final String LEGACY_REGION_ID = "global";
    private static final String MIGRATED_REGION_ID = "legacy_migrated";

    private final BlockRegen plugin;
    private final File randomOresFile;

    private FileConfiguration randomOresConfig;
    private final Map<String, RegionEntry> regionEntries = new HashMap<>();
    private final Map<String, Set<String>> pointToRegionsIndex = new HashMap<>();
    private final Map<String, Integer> relocationBlacklist = new HashMap<>();
    private final Map<String, RegionCycleDebug> regionDebugSnapshots = new HashMap<>();

    private boolean enabled;
    private long intervalTicks;
    private boolean strictRelocateEnabled;
    private int strictRelocateMinCycles;
    private int strictRelocateMaxCycles;

    public RandomOreManager(BlockRegen plugin) {
        this.plugin = plugin;
        this.randomOresFile = new File(plugin.getDataFolder(), "random-ores.yml");
        if (!this.randomOresFile.exists()) {
            plugin.saveResource("random-ores.yml", false);
        }
        this.randomOresConfig = YamlConfiguration.loadConfiguration(this.randomOresFile);
    }

    public void load() {
        this.randomOresConfig = YamlConfiguration.loadConfiguration(this.randomOresFile);
        this.regionEntries.clear();
        this.pointToRegionsIndex.clear();
        this.relocationBlacklist.clear();
        this.regionDebugSnapshots.clear();

        maybeAutoMigrateLegacyFormat();

        this.enabled = randomOresConfig.getBoolean("settings.enabled", false);
        long intervalSeconds = Math.max(1L, randomOresConfig.getLong("settings.interval-seconds", 30L));
        this.intervalTicks = intervalSeconds * 20L;
        loadStrictRelocateSettings();

        if (!loadRegionBasedConfig()) {
            loadLegacyConfig();
        }

        rebuildPointIndex();
    }

    private void loadStrictRelocateSettings() {
        this.strictRelocateEnabled = false;
        this.strictRelocateMinCycles = 1;
        this.strictRelocateMaxCycles = 2;

        Object node = randomOresConfig.get("settings.strict-relocate");
        if (node instanceof Boolean boolValue) {
            this.strictRelocateEnabled = boolValue;
            return;
        }

        ConfigurationSection section = randomOresConfig.getConfigurationSection("settings.strict-relocate");
        if (section != null) {
            this.strictRelocateEnabled = section.getBoolean("enabled", false);
            this.strictRelocateMinCycles = Math.max(1, section.getInt("min-cycles", 1));
            this.strictRelocateMaxCycles = Math.max(this.strictRelocateMinCycles, section.getInt("max-cycles", 2));
        }
    }

    private void maybeAutoMigrateLegacyFormat() {
        ConfigurationSection regionsSection = randomOresConfig.getConfigurationSection("regions");
        if (regionsSection != null && !regionsSection.getKeys(false).isEmpty()) {
            return;
        }

        ConfigurationSection legacyOres = randomOresConfig.getConfigurationSection("ores");
        if (legacyOres == null || legacyOres.getKeys(false).isEmpty()) {
            return;
        }

        int combinedMaxActive = 0;
        for (String blockId : legacyOres.getKeys(false)) {
            combinedMaxActive += Math.max(0, legacyOres.getInt(blockId + ".max-active", 1));

            ConfigurationSection oldBlockSection = legacyOres.getConfigurationSection(blockId);
            if (oldBlockSection == null) {
                continue;
            }

            String newPath = "regions." + MIGRATED_REGION_ID + ".blocks." + blockId;
            randomOresConfig.set(newPath + ".spawn-chance", oldBlockSection.getDouble("spawn-chance", 50.0D));
            randomOresConfig.set(newPath + ".empty-block", oldBlockSection.getString("empty-block", "STONE"));
            randomOresConfig.set(newPath + ".points", oldBlockSection.getStringList("points"));
        }

        randomOresConfig.set("regions." + MIGRATED_REGION_ID + ".max-active", Math.max(1, combinedMaxActive));
        randomOresConfig.set("ores", null);

        try {
            randomOresConfig.save(randomOresFile);
            plugin.getLogger().info("Migrasi otomatis random-ores.yml selesai: format lama 'ores' -> 'regions." + MIGRATED_REGION_ID + "'.");
        } catch (IOException ex) {
            plugin.getLogger().warning("Gagal migrasi otomatis random-ores.yml: " + ex.getMessage());
        }
    }

    private boolean loadRegionBasedConfig() {
        ConfigurationSection regionsSection = randomOresConfig.getConfigurationSection("regions");
        if (regionsSection == null) {
            return false;
        }

        for (String regionName : regionsSection.getKeys(false)) {
            ConfigurationSection regionSection = regionsSection.getConfigurationSection(regionName);
            if (regionSection == null) {
                continue;
            }

            int maxActive = Math.max(0, regionSection.getInt("max-active", 1));
            RegionEntry regionEntry = new RegionEntry(regionName, maxActive);

            ConfigurationSection blocksSection = regionSection.getConfigurationSection("blocks");
            if (blocksSection == null) {
                continue;
            }

            for (String blockIdentifier : blocksSection.getKeys(false)) {
                ConfigurationSection blockSection = blocksSection.getConfigurationSection(blockIdentifier);
                if (blockSection == null) {
                    continue;
                }

                BlockEntry blockEntry = parseBlockEntry(blockIdentifier, blockSection);
                if (blockEntry != null) {
                    regionEntry.blocks.put(blockIdentifier.toUpperCase(Locale.ROOT), blockEntry);
                }
            }

            if (!regionEntry.blocks.isEmpty()) {
                regionEntries.put(regionEntry.regionNameLower, regionEntry);
            }
        }

        return !regionEntries.isEmpty();
    }

    private void loadLegacyConfig() {
        ConfigurationSection oresSection = randomOresConfig.getConfigurationSection("ores");
        if (oresSection == null) {
            return;
        }

        RegionEntry legacyRegion = new RegionEntry(LEGACY_REGION_ID, Integer.MAX_VALUE);
        for (String identifier : oresSection.getKeys(false)) {
            ConfigurationSection oreSection = oresSection.getConfigurationSection(identifier);
            if (oreSection == null) {
                continue;
            }
            BlockEntry blockEntry = parseBlockEntry(identifier, oreSection);
            if (blockEntry != null) {
                legacyRegion.blocks.put(identifier.toUpperCase(Locale.ROOT), blockEntry);
            }
        }

        if (!legacyRegion.blocks.isEmpty()) {
            regionEntries.put(legacyRegion.regionNameLower, legacyRegion);
        }
    }

    private void rebuildPointIndex() {
        pointToRegionsIndex.clear();
        for (RegionEntry regionEntry : regionEntries.values()) {
            for (BlockEntry blockEntry : regionEntry.blocks.values()) {
                for (Location point : blockEntry.points) {
                    String key = pointKey(point);
                    pointToRegionsIndex.computeIfAbsent(key, ignored -> new HashSet<>()).add(regionEntry.regionNameLower);
                }
            }
        }
    }

    private BlockEntry parseBlockEntry(String identifier, ConfigurationSection section) {
        List<Location> points = new ArrayList<>();
        for (String rawPoint : section.getStringList("points")) {
            Location parsed = parsePoint(rawPoint);
            if (parsed != null) {
                points.add(parsed);
            }
        }

        if (points.isEmpty()) {
            return null;
        }

        String emptyBlockRaw = section.getString("empty-block", "");
        Material emptyBlock = parseMaterial(emptyBlockRaw);
        if (emptyBlock == null) {
            BlockData blockData = plugin.getBlockManager().getBlockData(identifier);
            emptyBlock = blockData != null ? blockData.getReplacedBlock() : Material.STONE;
        }

        double spawnChance = clampChance(section.getDouble("spawn-chance", 50.0D));
        return new BlockEntry(identifier, spawnChance, emptyBlock, points);
    }

    public boolean isEnabled() {
        return enabled && !regionEntries.isEmpty();
    }

    public long getIntervalTicks() {
        return intervalTicks;
    }

    public Collection<String> getRegionNames() {
        return new ArrayList<>(regionEntries.keySet());
    }

    public Collection<String> getConfiguredBlockIdentifiers(String regionName) {
        RegionEntry regionEntry = regionEntries.get(regionName.toLowerCase(Locale.ROOT));
        if (regionEntry == null) {
            return Collections.emptyList();
        }

        List<String> ids = new ArrayList<>();
        for (BlockEntry blockEntry : regionEntry.blocks.values()) {
            ids.add(blockEntry.blockIdentifier);
        }
        return ids;
    }

    public boolean addPoint(String regionName, String blockIdentifier, Location location) {
        if (regionName == null || regionName.isEmpty() || blockIdentifier == null || blockIdentifier.isEmpty() || location == null || location.getWorld() == null) {
            return false;
        }

        String normalizedRegion = regionName.toLowerCase(Locale.ROOT);
        String path = "regions." + normalizedRegion + ".blocks." + blockIdentifier;
        List<String> points = new ArrayList<>(randomOresConfig.getStringList(path + ".points"));
        String serialized = serializePoint(location);
        if (points.contains(serialized)) {
            return false;
        }

        points.add(serialized);
        randomOresConfig.set(path + ".points", points);
        if (!randomOresConfig.isSet("regions." + normalizedRegion + ".max-active")) {
            randomOresConfig.set("regions." + normalizedRegion + ".max-active", 1);
        }
        if (!randomOresConfig.isSet(path + ".spawn-chance")) {
            randomOresConfig.set(path + ".spawn-chance", 50.0D);
        }
        if (!randomOresConfig.isSet(path + ".empty-block")) {
            BlockData data = plugin.getBlockManager().getBlockData(blockIdentifier);
            randomOresConfig.set(path + ".empty-block", data != null ? data.getReplacedBlock().name() : Material.STONE.name());
        }

        return saveAndReload();
    }

    public boolean removePoint(String regionName, String blockIdentifier, Location location) {
        if (regionName == null || regionName.isEmpty() || blockIdentifier == null || blockIdentifier.isEmpty() || location == null || location.getWorld() == null) {
            return false;
        }

        String normalizedRegion = regionName.toLowerCase(Locale.ROOT);
        String path = "regions." + normalizedRegion + ".blocks." + blockIdentifier;
        List<String> points = new ArrayList<>(randomOresConfig.getStringList(path + ".points"));
        boolean removed = points.remove(serializePoint(location));
        if (!removed) {
            return false;
        }

        if (points.isEmpty()) {
            randomOresConfig.set(path, null);
        } else {
            randomOresConfig.set(path + ".points", points);
        }

        ConfigurationSection blocksSection = randomOresConfig.getConfigurationSection("regions." + normalizedRegion + ".blocks");
        if (blocksSection != null && blocksSection.getKeys(false).isEmpty()) {
            randomOresConfig.set("regions." + normalizedRegion, null);
        }

        return saveAndReload();
    }

    public int getPointCount(String regionName, String blockIdentifier) {
        RegionEntry regionEntry = regionEntries.get(regionName.toLowerCase(Locale.ROOT));
        if (regionEntry == null) {
            return 0;
        }

        BlockEntry blockEntry = regionEntry.blocks.get(blockIdentifier.toUpperCase(Locale.ROOT));
        return blockEntry == null ? 0 : blockEntry.points.size();
    }

    public int refreshRegionNow(String regionName) {
        advanceBlacklistCycle();
        if (regionName == null || regionName.isEmpty() || regionName.equalsIgnoreCase("all")) {
            randomizeNow();
            return regionEntries.size();
        }

        RegionEntry regionEntry = regionEntries.get(regionName.toLowerCase(Locale.ROOT));
        if (regionEntry == null) {
            return 0;
        }
        randomizeRegion(regionEntry, Collections.emptySet());
        return 1;
    }

    public int spawnBlockInRegion(String regionName, String blockIdentifier, int amount) {
        if (amount <= 0) {
            return 0;
        }

        RegionEntry regionEntry = regionEntries.get(regionName.toLowerCase(Locale.ROOT));
        if (regionEntry == null) {
            return 0;
        }

        BlockEntry blockEntry = regionEntry.blocks.get(blockIdentifier.toUpperCase(Locale.ROOT));
        if (blockEntry == null) {
            return 0;
        }

        List<Location> points = new ArrayList<>(blockEntry.points);
        Collections.shuffle(points);

        int placed = 0;
        for (Location point : points) {
            if (placed >= amount) {
                break;
            }
            if (plugin.getRegenManager().isRegenerating(point) || plugin.getMiningManager().isBeingMined(point)) {
                continue;
            }

            clearToEmpty(blockEntry.emptyBlock, point);
            if (placeIdentifier(blockEntry.blockIdentifier, point)) {
                placed++;
            }
        }

        return placed;
    }

    public void randomizeNow() {
        advanceBlacklistCycle();
        for (RegionEntry regionEntry : regionEntries.values()) {
            randomizeRegion(regionEntry, Collections.emptySet());
        }
    }

    public boolean isManagedPoint(Location location) {
        if (location == null || location.getWorld() == null) {
            return false;
        }
        return pointToRegionsIndex.containsKey(pointKey(location));
    }

    public void onPointRegenerated(Location location) {
        if (!enabled || location == null || location.getWorld() == null) {
            return;
        }

        String regeneratedKey = pointKey(location);
        if (strictRelocateEnabled) {
            int cycles = ThreadLocalRandom.current().nextInt(strictRelocateMinCycles, strictRelocateMaxCycles + 1);
            relocationBlacklist.put(regeneratedKey, cycles);
        }

        Set<String> regions = pointToRegionsIndex.get(regeneratedKey);
        if (regions == null || regions.isEmpty()) {
            return;
        }

        for (String regionName : regions) {
            RegionEntry regionEntry = regionEntries.get(regionName);
            if (regionEntry != null) {
                randomizeRegion(regionEntry, Collections.singleton(regeneratedKey));
            }
        }
    }

    public List<String> getRegionDebugLines(String regionName) {
        RegionCycleDebug debug = regionDebugSnapshots.get(regionName.toLowerCase(Locale.ROOT));
        if (debug == null) {
            return Collections.emptyList();
        }

        List<String> lines = new ArrayList<>();
        lines.add("&eRegion: &f" + debug.regionName);
        lines.add("&eCycle: &f" + debug.cycleTimeMs);
        lines.add("&eTotal point: &f" + debug.totalPoints + " &7| &eCap: &f" + debug.cap);
        lines.add("&eSelected: &a" + debug.selected.size());
        lines.add("&eSkip blacklist: &c" + debug.skippedBlacklist + " &7| &eSkip mining: &c" + debug.skippedMining + " &7| &eSkip regen: &c" + debug.skippedRegen);
        for (String selected : debug.selected) {
            lines.add("&7- &f" + selected);
        }
        return lines;
    }

    private void advanceBlacklistCycle() {
        if (relocationBlacklist.isEmpty()) {
            return;
        }

        List<String> toRemove = new ArrayList<>();
        for (Map.Entry<String, Integer> entry : relocationBlacklist.entrySet()) {
            int next = entry.getValue() - 1;
            if (next <= 0) {
                toRemove.add(entry.getKey());
            } else {
                entry.setValue(next);
            }
        }
        for (String key : toRemove) {
            relocationBlacklist.remove(key);
        }
    }

    private void randomizeRegion(RegionEntry regionEntry, Set<String> excludedKeys) {
        Map<String, PointMeta> allPoints = new HashMap<>();
        List<BlockEntry> weightedBlocks = new ArrayList<>();
        int skippedBlacklist = 0;
        int skippedMining = 0;
        int skippedRegen = 0;
        List<String> selectedPoints = new ArrayList<>();

        for (BlockEntry blockEntry : regionEntry.blocks.values()) {
            if (blockEntry.spawnChance > 0.0D) {
                weightedBlocks.add(blockEntry);
            }

            for (Location point : blockEntry.points) {
                String key = pointKey(point);
                allPoints.putIfAbsent(key, new PointMeta(point, blockEntry.emptyBlock));
            }
        }

        if (allPoints.isEmpty()) {
            return;
        }

        List<PointMeta> availablePoints = new ArrayList<>();
        int reservedActiveSlots = 0;
        for (PointMeta meta : allPoints.values()) {
            String key = pointKey(meta.location);
            if (excludedKeys.contains(key)) {
                clearToEmpty(meta.emptyBlock, meta.location);
                continue;
            }

            if (strictRelocateEnabled && relocationBlacklist.containsKey(key)) {
                skippedBlacklist++;
                continue;
            }

            if (plugin.getRegenManager().isRegenerating(meta.location)) {
                skippedRegen++;
                continue;
            }

            if (plugin.getMiningManager().isBeingMined(meta.location)) {
                if (isRegionBlockAtLocation(regionEntry, meta.location)) {
                    reservedActiveSlots++;
                }
                skippedMining++;
                continue;
            }
            clearToEmpty(meta.emptyBlock, meta.location);
            availablePoints.add(meta);
        }

        if (availablePoints.isEmpty()) {
            return;
        }

        if (weightedBlocks.isEmpty() || regionEntry.maxActive <= 0) {
            return;
        }

        Collections.shuffle(availablePoints);
        int freeSlots = Math.max(0, regionEntry.maxActive - reservedActiveSlots);
        int cap = Math.min(freeSlots, availablePoints.size());
        for (int i = 0; i < cap; i++) {
            BlockEntry chosen = selectWeightedBlock(weightedBlocks);
            if (chosen != null) {
                PointMeta pointMeta = availablePoints.get(i);
                if (placeIdentifier(chosen.blockIdentifier, pointMeta.location)) {
                    selectedPoints.add(chosen.blockIdentifier + " @ " + serializePoint(pointMeta.location));
                }
            }
        }

        regionDebugSnapshots.put(regionEntry.regionNameLower,
                new RegionCycleDebug(regionEntry.regionNameLower, System.currentTimeMillis(), allPoints.size(), cap,
                        skippedBlacklist, skippedMining, skippedRegen, selectedPoints));
    }

    private boolean isRegionBlockAtLocation(RegionEntry regionEntry, Location location) {
        String identifier = plugin.getMiningManager().getBlockIdentifier(location.getBlock());
        if (identifier == null) {
            return false;
        }
        return regionEntry.blocks.containsKey(identifier.toUpperCase(Locale.ROOT));
    }

    private BlockEntry selectWeightedBlock(List<BlockEntry> blocks) {
        double total = 0.0D;
        for (BlockEntry entry : blocks) {
            total += entry.spawnChance;
        }

        if (total <= 0.0D) {
            return null;
        }

        double roll = ThreadLocalRandom.current().nextDouble(total);
        double cumulative = 0.0D;
        for (BlockEntry entry : blocks) {
            cumulative += entry.spawnChance;
            if (roll < cumulative) {
                return entry;
            }
        }

        return blocks.get(blocks.size() - 1);
    }

    private boolean placeIdentifier(String blockIdentifier, Location location) {
        boolean placed = false;

        BlockData data = plugin.getBlockManager().getBlockData(blockIdentifier);
        if (data != null) {
            String actualBlockId = data.getBlockId();
            if (actualBlockId != null && !actualBlockId.isEmpty()) {
                String lower = actualBlockId.toLowerCase(Locale.ROOT);
                if (lower.startsWith("nexo:")) {
                    placed = BlockRegen.nexoEnabled && NexoUtil.placeNexoBlock(actualBlockId, location);
                } else if (actualBlockId.contains(":")) {
                    if (BlockRegen.itemsAdderEnabled) {
                        try {
                            placed = CustomBlock.place(actualBlockId, location) != null;
                        } catch (Throwable ignored) {
                            placed = false;
                        }
                    }
                } else {
                    Material material = parseMaterial(actualBlockId);
                    if (material != null) {
                        location.getBlock().setType(material, false);
                        placed = true;
                    }
                }
            }
        }

        if (!placed) {
            if (blockIdentifier.toLowerCase(Locale.ROOT).startsWith("nexo:")) {
                placed = BlockRegen.nexoEnabled && NexoUtil.placeNexoBlock(blockIdentifier, location);
            } else if (blockIdentifier.contains(":")) {
                if (!BlockRegen.itemsAdderEnabled) {
                    placed = false;
                } else {
                    try {
                        placed = CustomBlock.place(blockIdentifier, location) != null;
                    } catch (Throwable ignored) {
                        placed = false;
                    }
                }
            } else {
                Material material = parseMaterial(blockIdentifier);
                if (material == null) {
                    placed = false;
                } else {
                    location.getBlock().setType(material, false);
                    placed = true;
                }
            }
        }

        // Setelah blok berhasil ditempatkan, spawn model jika dikonfigurasi
        if (placed && BlockRegen.modelEngineEnabled) {
            if (data != null && data.hasModelEngine()) {
                ModelEngineUtil.spawnModel(
                        location,
                        data.getModelEngineId(),
                        data.getModelYaw(),
                        data.getModelHeightOffset(),
                        data.isModelHideBlock()
                );
            }
        }

        return placed;
    }

    private void clearToEmpty(Material material, Location location) {
        if (location == null || material == null) return;
        // Batalkan mining task yang mungkin sedang aktif di lokasi ini
        plugin.getMiningManager().cancelMiningAt(location);
        // Hapus model Engine jika ada (termasuk kembalikan hidden block)
        if (BlockRegen.modelEngineEnabled) {
            ModelEngineUtil.removeModel(location);
            ModelEngineUtil.restoreHiddenBlock(location);
        }
        NexoUtil.removeNexoBlock(location);
        location.getBlock().setType(material, false);
    }

    private boolean saveAndReload() {
        try {
            randomOresConfig.save(randomOresFile);
            load();
            return true;
        } catch (IOException ex) {
            plugin.getLogger().severe("Gagal menyimpan random-ores.yml: " + ex.getMessage());
            return false;
        }
    }

    private Material parseMaterial(String raw) {
        if (raw == null || raw.isEmpty()) {
            return null;
        }
        try {
            return Material.valueOf(raw.toUpperCase(Locale.ROOT));
        } catch (IllegalArgumentException ignored) {
            return null;
        }
    }

    private double clampChance(double chance) {
        return Math.max(0.0D, Math.min(100.0D, chance));
    }

    private String serializePoint(Location location) {
        return location.getWorld().getName() + "," + location.getBlockX() + "," + location.getBlockY() + "," + location.getBlockZ();
    }

    private String pointKey(Location location) {
        return serializePoint(location);
    }

    private Location parsePoint(String raw) {
        if (raw == null || raw.isEmpty()) {
            return null;
        }

        String[] parts = raw.split(",");
        if (parts.length != 4) {
            return null;
        }

        World world = Bukkit.getWorld(parts[0]);
        if (world == null) {
            return null;
        }

        try {
            int x = Integer.parseInt(parts[1]);
            int y = Integer.parseInt(parts[2]);
            int z = Integer.parseInt(parts[3]);
            return new Location(world, x, y, z);
        } catch (NumberFormatException ex) {
            return null;
        }
    }

    private static final class RegionEntry {
        private final String regionNameLower;
        private final int maxActive;
        private final Map<String, BlockEntry> blocks = new HashMap<>();

        private RegionEntry(String regionName, int maxActive) {
            this.regionNameLower = regionName.toLowerCase(Locale.ROOT);
            this.maxActive = maxActive;
        }
    }

    private static final class BlockEntry {
        private final String blockIdentifier;
        private final double spawnChance;
        private final Material emptyBlock;
        private final List<Location> points;

        private BlockEntry(String blockIdentifier, double spawnChance, Material emptyBlock, List<Location> points) {
            this.blockIdentifier = blockIdentifier;
            this.spawnChance = spawnChance;
            this.emptyBlock = emptyBlock;
            this.points = points;
        }
    }

    private static final class PointMeta {
        private final Location location;
        private final Material emptyBlock;

        private PointMeta(Location location, Material emptyBlock) {
            this.location = location;
            this.emptyBlock = emptyBlock;
        }
    }

    private static final class RegionCycleDebug {
        private final String regionName;
        private final long cycleTimeMs;
        private final int totalPoints;
        private final int cap;
        private final int skippedBlacklist;
        private final int skippedMining;
        private final int skippedRegen;
        private final List<String> selected;

        private RegionCycleDebug(String regionName, long cycleTimeMs, int totalPoints, int cap,
                                 int skippedBlacklist, int skippedMining, int skippedRegen, List<String> selected) {
            this.regionName = regionName;
            this.cycleTimeMs = cycleTimeMs;
            this.totalPoints = totalPoints;
            this.cap = cap;
            this.skippedBlacklist = skippedBlacklist;
            this.skippedMining = skippedMining;
            this.skippedRegen = skippedRegen;
            this.selected = selected;
        }
    }
}

package me.allync.blockregen.manager;

import dev.lone.itemsadder.api.CustomBlock;
import me.allync.blockregen.BlockRegen;
import me.allync.blockregen.data.BlockData;
import me.allync.blockregen.util.ModelEngineUtil;
import me.allync.blockregen.util.NexoUtil;
import org.bukkit.Bukkit;
import org.bukkit.Location;
import org.bukkit.Material;
import org.bukkit.World;
import org.bukkit.configuration.ConfigurationSection;
import org.bukkit.configuration.file.FileConfiguration;
import org.bukkit.configuration.file.YamlConfiguration;

import java.io.File;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ThreadLocalRandom;

public class RandomOreManager {

    private static final String LEGACY_REGION_ID = "global";
    private static final String MIGRATED_REGION_ID = "legacy_migrated";

    private final BlockRegen plugin;
    private final File randomOresFile;

    private FileConfiguration randomOresConfig;
    private final Map<String, RegionEntry> regionEntries = new HashMap<>();
    private final Map<String, Set<String>> pointToRegionsIndex = new HashMap<>();
    private final Map<String, Integer> relocationBlacklist = new HashMap<>();
    private final Map<String, RegionCycleDebug> regionDebugSnapshots = new HashMap<>();

    private boolean enabled;
    private long intervalTicks;
    private boolean strictRelocateEnabled;
    private int strictRelocateMinCycles;
    private int strictRelocateMaxCycles;

    public RandomOreManager(BlockRegen plugin) {
        this.plugin = plugin;
        this.randomOresFile = new File(plugin.getDataFolder(), "random-ores.yml");
        if (!this.randomOresFile.exists()) {
            plugin.saveResource("random-ores.yml", false);
        }
        this.randomOresConfig = YamlConfiguration.loadConfiguration(this.randomOresFile);
    }

    public void load() {
        this.randomOresConfig = YamlConfiguration.loadConfiguration(this.randomOresFile);
        this.regionEntries.clear();
        this.pointToRegionsIndex.clear();
        this.relocationBlacklist.clear();
        this.regionDebugSnapshots.clear();

        maybeAutoMigrateLegacyFormat();

        this.enabled = randomOresConfig.getBoolean("settings.enabled", false);
        long intervalSeconds = Math.max(1L, randomOresConfig.getLong("settings.interval-seconds", 30L));
        this.intervalTicks = intervalSeconds * 20L;
        loadStrictRelocateSettings();

        if (!loadRegionBasedConfig()) {
            loadLegacyConfig();
        }

        rebuildPointIndex();
    }

    private void loadStrictRelocateSettings() {
        this.strictRelocateEnabled = false;
        this.strictRelocateMinCycles = 1;
        this.strictRelocateMaxCycles = 2;

        Object node = randomOresConfig.get("settings.strict-relocate");
        if (node instanceof Boolean boolValue) {
            this.strictRelocateEnabled = boolValue;
            return;
        }

        ConfigurationSection section = randomOresConfig.getConfigurationSection("settings.strict-relocate");
        if (section != null) {
            this.strictRelocateEnabled = section.getBoolean("enabled", false);
            this.strictRelocateMinCycles = Math.max(1, section.getInt("min-cycles", 1));
            this.strictRelocateMaxCycles = Math.max(this.strictRelocateMinCycles, section.getInt("max-cycles", 2));
        }
    }

    private void maybeAutoMigrateLegacyFormat() {
        ConfigurationSection regionsSection = randomOresConfig.getConfigurationSection("regions");
        if (regionsSection != null && !regionsSection.getKeys(false).isEmpty()) {
            return;
        }

        ConfigurationSection legacyOres = randomOresConfig.getConfigurationSection("ores");
        if (legacyOres == null || legacyOres.getKeys(false).isEmpty()) {
            return;
        }

        int combinedMaxActive = 0;
        for (String blockId : legacyOres.getKeys(false)) {
            combinedMaxActive += Math.max(0, legacyOres.getInt(blockId + ".max-active", 1));

            ConfigurationSection oldBlockSection = legacyOres.getConfigurationSection(blockId);
            if (oldBlockSection == null) {
                continue;
            }

            String newPath = "regions." + MIGRATED_REGION_ID + ".blocks." + blockId;
            randomOresConfig.set(newPath + ".spawn-chance", oldBlockSection.getDouble("spawn-chance", 50.0D));
            randomOresConfig.set(newPath + ".empty-block", oldBlockSection.getString("empty-block", "STONE"));
            randomOresConfig.set(newPath + ".points", oldBlockSection.getStringList("points"));
        }

        randomOresConfig.set("regions." + MIGRATED_REGION_ID + ".max-active", Math.max(1, combinedMaxActive));
        randomOresConfig.set("ores", null);

        try {
            randomOresConfig.save(randomOresFile);
            plugin.getLogger().info("Migrasi otomatis random-ores.yml selesai: format lama 'ores' -> 'regions." + MIGRATED_REGION_ID + "'.");
        } catch (IOException ex) {
            plugin.getLogger().warning("Gagal migrasi otomatis random-ores.yml: " + ex.getMessage());
        }
    }

    private boolean loadRegionBasedConfig() {
        ConfigurationSection regionsSection = randomOresConfig.getConfigurationSection("regions");
        if (regionsSection == null) {
            return false;
        }

        for (String regionName : regionsSection.getKeys(false)) {
            ConfigurationSection regionSection = regionsSection.getConfigurationSection(regionName);
            if (regionSection == null) {
                continue;
            }

            int maxActive = Math.max(0, regionSection.getInt("max-active", 1));
            RegionEntry regionEntry = new RegionEntry(regionName, maxActive);

            ConfigurationSection blocksSection = regionSection.getConfigurationSection("blocks");
            if (blocksSection == null) {
                continue;
            }

            for (String blockIdentifier : blocksSection.getKeys(false)) {
                ConfigurationSection blockSection = blocksSection.getConfigurationSection(blockIdentifier);
                if (blockSection == null) {
                    continue;
                }

                BlockEntry blockEntry = parseBlockEntry(blockIdentifier, blockSection);
                if (blockEntry != null) {
                    regionEntry.blocks.put(blockIdentifier.toUpperCase(Locale.ROOT), blockEntry);
                }
            }

            if (!regionEntry.blocks.isEmpty()) {
                regionEntries.put(regionEntry.regionNameLower, regionEntry);
            }
        }

        return !regionEntries.isEmpty();
    }

    private void loadLegacyConfig() {
        ConfigurationSection oresSection = randomOresConfig.getConfigurationSection("ores");
        if (oresSection == null) {
            return;
        }

        RegionEntry legacyRegion = new RegionEntry(LEGACY_REGION_ID, Integer.MAX_VALUE);
        for (String identifier : oresSection.getKeys(false)) {
            ConfigurationSection oreSection = oresSection.getConfigurationSection(identifier);
            if (oreSection == null) {
                continue;
            }
            BlockEntry blockEntry = parseBlockEntry(identifier, oreSection);
            if (blockEntry != null) {
                legacyRegion.blocks.put(identifier.toUpperCase(Locale.ROOT), blockEntry);
            }
        }

        if (!legacyRegion.blocks.isEmpty()) {
            regionEntries.put(legacyRegion.regionNameLower, legacyRegion);
        }
    }

    private void rebuildPointIndex() {
        pointToRegionsIndex.clear();
        for (RegionEntry regionEntry : regionEntries.values()) {
            for (BlockEntry blockEntry : regionEntry.blocks.values()) {
                for (Location point : blockEntry.points) {
                    String key = pointKey(point);
                    pointToRegionsIndex.computeIfAbsent(key, ignored -> new HashSet<>()).add(regionEntry.regionNameLower);
                }
            }
        }
    }

    private BlockEntry parseBlockEntry(String identifier, ConfigurationSection section) {
        List<Location> points = new ArrayList<>();
        for (String rawPoint : section.getStringList("points")) {
            Location parsed = parsePoint(rawPoint);
            if (parsed != null) {
                points.add(parsed);
            }
        }

        if (points.isEmpty()) {
            return null;
        }

        String emptyBlockRaw = section.getString("empty-block", "");
        Material emptyBlock = parseMaterial(emptyBlockRaw);
        if (emptyBlock == null) {
            BlockData blockData = plugin.getBlockManager().getBlockData(identifier);
            emptyBlock = blockData != null ? blockData.getReplacedBlock() : Material.STONE;
        }

        double spawnChance = clampChance(section.getDouble("spawn-chance", 50.0D));
        return new BlockEntry(identifier, spawnChance, emptyBlock, points);
    }

    public boolean isEnabled() {
        return enabled && !regionEntries.isEmpty();
    }

    public long getIntervalTicks() {
        return intervalTicks;
    }

    public Collection<String> getRegionNames() {
        return new ArrayList<>(regionEntries.keySet());
    }

    public Collection<String> getConfiguredBlockIdentifiers(String regionName) {
        RegionEntry regionEntry = regionEntries.get(regionName.toLowerCase(Locale.ROOT));
        if (regionEntry == null) {
            return Collections.emptyList();
        }

        List<String> ids = new ArrayList<>();
        for (BlockEntry blockEntry : regionEntry.blocks.values()) {
            ids.add(blockEntry.blockIdentifier);
        }
        return ids;
    }

    public boolean addPoint(String regionName, String blockIdentifier, Location location) {
        if (regionName == null || regionName.isEmpty() || blockIdentifier == null || blockIdentifier.isEmpty() || location == null || location.getWorld() == null) {
            return false;
        }

        String normalizedRegion = regionName.toLowerCase(Locale.ROOT);
        String path = "regions." + normalizedRegion + ".blocks." + blockIdentifier;
        List<String> points = new ArrayList<>(randomOresConfig.getStringList(path + ".points"));
        String serialized = serializePoint(location);
        if (points.contains(serialized)) {
            return false;
        }

        points.add(serialized);
        randomOresConfig.set(path + ".points", points);
        if (!randomOresConfig.isSet("regions." + normalizedRegion + ".max-active")) {
            randomOresConfig.set("regions." + normalizedRegion + ".max-active", 1);
        }
        if (!randomOresConfig.isSet(path + ".spawn-chance")) {
            randomOresConfig.set(path + ".spawn-chance", 50.0D);
        }
        if (!randomOresConfig.isSet(path + ".empty-block")) {
            BlockData data = plugin.getBlockManager().getBlockData(blockIdentifier);
            randomOresConfig.set(path + ".empty-block", data != null ? data.getReplacedBlock().name() : Material.STONE.name());
        }

        return saveAndReload();
    }

    public boolean removePoint(String regionName, String blockIdentifier, Location location) {
        if (regionName == null || regionName.isEmpty() || blockIdentifier == null || blockIdentifier.isEmpty() || location == null || location.getWorld() == null) {
            return false;
        }

        String normalizedRegion = regionName.toLowerCase(Locale.ROOT);
        String path = "regions." + normalizedRegion + ".blocks." + blockIdentifier;
        List<String> points = new ArrayList<>(randomOresConfig.getStringList(path + ".points"));
        boolean removed = points.remove(serializePoint(location));
        if (!removed) {
            return false;
        }

        if (points.isEmpty()) {
            randomOresConfig.set(path, null);
        } else {
            randomOresConfig.set(path + ".points", points);
        }

        ConfigurationSection blocksSection = randomOresConfig.getConfigurationSection("regions." + normalizedRegion + ".blocks");
        if (blocksSection != null && blocksSection.getKeys(false).isEmpty()) {
            randomOresConfig.set("regions." + normalizedRegion, null);
        }

        return saveAndReload();
    }

    public int getPointCount(String regionName, String blockIdentifier) {
        RegionEntry regionEntry = regionEntries.get(regionName.toLowerCase(Locale.ROOT));
        if (regionEntry == null) {
            return 0;
        }

        BlockEntry blockEntry = regionEntry.blocks.get(blockIdentifier.toUpperCase(Locale.ROOT));
        return blockEntry == null ? 0 : blockEntry.points.size();
    }

    public int refreshRegionNow(String regionName) {
        advanceBlacklistCycle();
        if (regionName == null || regionName.isEmpty() || regionName.equalsIgnoreCase("all")) {
            randomizeNow();
            return regionEntries.size();
        }

        RegionEntry regionEntry = regionEntries.get(regionName.toLowerCase(Locale.ROOT));
        if (regionEntry == null) {
            return 0;
        }
        randomizeRegion(regionEntry, Collections.emptySet());
        return 1;
    }

    public int spawnBlockInRegion(String regionName, String blockIdentifier, int amount) {
        if (amount <= 0) {
            return 0;
        }

        RegionEntry regionEntry = regionEntries.get(regionName.toLowerCase(Locale.ROOT));
        if (regionEntry == null) {
            return 0;
        }

        BlockEntry blockEntry = regionEntry.blocks.get(blockIdentifier.toUpperCase(Locale.ROOT));
        if (blockEntry == null) {
            return 0;
        }

        List<Location> points = new ArrayList<>(blockEntry.points);
        Collections.shuffle(points);

        int placed = 0;
        for (Location point : points) {
            if (placed >= amount) {
                break;
            }
            if (plugin.getRegenManager().isRegenerating(point) || plugin.getMiningManager().isBeingMined(point)) {
                continue;
            }

            clearToEmpty(blockEntry.emptyBlock, point);
            if (placeIdentifier(blockEntry.blockIdentifier, point)) {
                placed++;
            }
        }

        return placed;
    }

    public void randomizeNow() {
        advanceBlacklistCycle();
        for (RegionEntry regionEntry : regionEntries.values()) {
            randomizeRegion(regionEntry, Collections.emptySet());
        }
    }

    public boolean isManagedPoint(Location location) {
        if (location == null || location.getWorld() == null) {
            return false;
        }
        return pointToRegionsIndex.containsKey(pointKey(location));
    }

    public void onPointRegenerated(Location location) {
        if (!enabled || location == null || location.getWorld() == null) {
            return;
        }

        String regeneratedKey = pointKey(location);
        if (strictRelocateEnabled) {
            int cycles = ThreadLocalRandom.current().nextInt(strictRelocateMinCycles, strictRelocateMaxCycles + 1);
            relocationBlacklist.put(regeneratedKey, cycles);
        }

        Set<String> regions = pointToRegionsIndex.get(regeneratedKey);
        if (regions == null || regions.isEmpty()) {
            return;
        }

        for (String regionName : regions) {
            RegionEntry regionEntry = regionEntries.get(regionName);
            if (regionEntry != null) {
                randomizeRegion(regionEntry, Collections.singleton(regeneratedKey));
            }
        }
    }

    public List<String> getRegionDebugLines(String regionName) {
        RegionCycleDebug debug = regionDebugSnapshots.get(regionName.toLowerCase(Locale.ROOT));
        if (debug == null) {
            return Collections.emptyList();
        }

        List<String> lines = new ArrayList<>();
        lines.add("&eRegion: &f" + debug.regionName);
        lines.add("&eCycle: &f" + debug.cycleTimeMs);
        lines.add("&eTotal point: &f" + debug.totalPoints + " &7| &eCap: &f" + debug.cap);
        lines.add("&eSelected: &a" + debug.selected.size());
        lines.add("&eSkip blacklist: &c" + debug.skippedBlacklist + " &7| &eSkip mining: &c" + debug.skippedMining + " &7| &eSkip regen: &c" + debug.skippedRegen);
        for (String selected : debug.selected) {
            lines.add("&7- &f" + selected);
        }
        return lines;
    }

    private void advanceBlacklistCycle() {
        if (relocationBlacklist.isEmpty()) {
            return;
        }

        List<String> toRemove = new ArrayList<>();
        for (Map.Entry<String, Integer> entry : relocationBlacklist.entrySet()) {
            int next = entry.getValue() - 1;
            if (next <= 0) {
                toRemove.add(entry.getKey());
            } else {
                entry.setValue(next);
            }
        }
        for (String key : toRemove) {
            relocationBlacklist.remove(key);
        }
    }

    private void randomizeRegion(RegionEntry regionEntry, Set<String> excludedKeys) {
        Map<String, PointMeta> allPoints = new HashMap<>();
        List<BlockEntry> weightedBlocks = new ArrayList<>();
        int skippedBlacklist = 0;
        int skippedMining = 0;
        int skippedRegen = 0;
        List<String> selectedPoints = new ArrayList<>();

        for (BlockEntry blockEntry : regionEntry.blocks.values()) {
            if (blockEntry.spawnChance > 0.0D) {
                weightedBlocks.add(blockEntry);
            }

            for (Location point : blockEntry.points) {
                String key = pointKey(point);
                allPoints.putIfAbsent(key, new PointMeta(point, blockEntry.emptyBlock));
            }
        }

        if (allPoints.isEmpty()) {
            return;
        }

        List<PointMeta> availablePoints = new ArrayList<>();
        int reservedActiveSlots = 0;
        for (PointMeta meta : allPoints.values()) {
            String key = pointKey(meta.location);
            if (excludedKeys.contains(key)) {
                clearToEmpty(meta.emptyBlock, meta.location);
                continue;
            }

            if (strictRelocateEnabled && relocationBlacklist.containsKey(key)) {
                skippedBlacklist++;
                continue;
            }

            if (plugin.getRegenManager().isRegenerating(meta.location)) {
                skippedRegen++;
                continue;
            }

            if (plugin.getMiningManager().isBeingMined(meta.location)) {
                if (isRegionBlockAtLocation(regionEntry, meta.location)) {
                    reservedActiveSlots++;
                }
                skippedMining++;
                continue;
            }
            clearToEmpty(meta.emptyBlock, meta.location);
            availablePoints.add(meta);
        }

        if (availablePoints.isEmpty()) {
            return;
        }

        if (weightedBlocks.isEmpty() || regionEntry.maxActive <= 0) {
            return;
        }

        Collections.shuffle(availablePoints);
        int freeSlots = Math.max(0, regionEntry.maxActive - reservedActiveSlots);
        int cap = Math.min(freeSlots, availablePoints.size());
        for (int i = 0; i < cap; i++) {
            BlockEntry chosen = selectWeightedBlock(weightedBlocks);
            if (chosen != null) {
                PointMeta pointMeta = availablePoints.get(i);
                if (placeIdentifier(chosen.blockIdentifier, pointMeta.location)) {
                    selectedPoints.add(chosen.blockIdentifier + " @ " + serializePoint(pointMeta.location));
                }
            }
        }

        regionDebugSnapshots.put(regionEntry.regionNameLower,
                new RegionCycleDebug(regionEntry.regionNameLower, System.currentTimeMillis(), allPoints.size(), cap,
                        skippedBlacklist, skippedMining, skippedRegen, selectedPoints));
    }

    private boolean isRegionBlockAtLocation(RegionEntry regionEntry, Location location) {
        java.util.Set<String> regionNames = plugin.getRegionManager().getRegionNamesAt(location);
        String identifier = plugin.getMiningManager().getBlockIdentifier(location.getBlock(), regionNames);
        if (identifier == null) {
            return false;
        }
        return regionEntry.blocks.containsKey(identifier.toUpperCase(Locale.ROOT));
    }

    private BlockEntry selectWeightedBlock(List<BlockEntry> blocks) {
        double total = 0.0D;
        for (BlockEntry entry : blocks) {
            total += entry.spawnChance;
        }

        if (total <= 0.0D) {
            return null;
        }

        double roll = ThreadLocalRandom.current().nextDouble(total);
        double cumulative = 0.0D;
        for (BlockEntry entry : blocks) {
            cumulative += entry.spawnChance;
            if (roll < cumulative) {
                return entry;
            }
        }

        return blocks.get(blocks.size() - 1);
    }

    private boolean placeIdentifier(String blockIdentifier, Location location) {
        boolean placed = false;

        BlockData data = plugin.getBlockManager().getBlockData(blockIdentifier);
        if (data != null) {
            String actualBlockId = data.getBlockId();
            if (actualBlockId != null && !actualBlockId.isEmpty()) {
                String lower = actualBlockId.toLowerCase(Locale.ROOT);
                if (lower.startsWith("nexo:")) {
                    placed = BlockRegen.nexoEnabled && NexoUtil.placeNexoBlock(actualBlockId, location);
                } else if (actualBlockId.contains(":")) {
                    if (BlockRegen.itemsAdderEnabled) {
                        try {
                            placed = CustomBlock.place(actualBlockId, location) != null;
                        } catch (Throwable ignored) {
                            placed = false;
                        }
                    }
                } else {
                    Material material = parseMaterial(actualBlockId);
                    if (material != null) {
                        location.getBlock().setType(material, false);
                        placed = true;
                    }
                }
            }
        }

        if (!placed) {
            if (blockIdentifier.toLowerCase(Locale.ROOT).startsWith("nexo:")) {
                placed = BlockRegen.nexoEnabled && NexoUtil.placeNexoBlock(blockIdentifier, location);
            } else if (blockIdentifier.contains(":")) {
                if (!BlockRegen.itemsAdderEnabled) {
                    placed = false;
                } else {
                    try {
                        placed = CustomBlock.place(blockIdentifier, location) != null;
                    } catch (Throwable ignored) {
                        placed = false;
                    }
                }
            } else {
                Material material = parseMaterial(blockIdentifier);
                if (material == null) {
                    placed = false;
                } else {
                    location.getBlock().setType(material, false);
                    placed = true;
                }
            }
        }

        // Setelah blok berhasil ditempatkan, spawn model jika dikonfigurasi
        if (placed && BlockRegen.modelEngineEnabled) {
            if (data != null && data.hasModelEngine()) {
                ModelEngineUtil.spawnModel(
                        location,
                        data.getModelEngineId(),
                        data.getModelYaw(),
                        data.getModelHeightOffset(),
                        data.isModelHideBlock()
                );
            }
        }

        return placed;
    }

    private void clearToEmpty(Material material, Location location) {
        if (location == null || material == null) return;
        // Batalkan mining task yang mungkin sedang aktif di lokasi ini
        plugin.getMiningManager().cancelMiningAt(location);
        // Hapus model Engine jika ada (termasuk kembalikan hidden block)
        if (BlockRegen.modelEngineEnabled) {
            ModelEngineUtil.removeModel(location);
            ModelEngineUtil.restoreHiddenBlock(location);
        }
        NexoUtil.removeNexoBlock(location);
        location.getBlock().setType(material, false);
    }

    private boolean saveAndReload() {
        try {
            randomOresConfig.save(randomOresFile);
            load();
            return true;
        } catch (IOException ex) {
            plugin.getLogger().severe("Gagal menyimpan random-ores.yml: " + ex.getMessage());
            return false;
        }
    }

    private Material parseMaterial(String raw) {
        if (raw == null || raw.isEmpty()) {
            return null;
        }
        try {
            return Material.valueOf(raw.toUpperCase(Locale.ROOT));
        } catch (IllegalArgumentException ignored) {
            return null;
        }
    }

    private double clampChance(double chance) {
        return Math.max(0.0D, Math.min(100.0D, chance));
    }

    private String serializePoint(Location location) {
        return location.getWorld().getName() + "," + location.getBlockX() + "," + location.getBlockY() + "," + location.getBlockZ();
    }

    private String pointKey(Location location) {
        return serializePoint(location);
    }

    private Location parsePoint(String raw) {
        if (raw == null || raw.isEmpty()) {
            return null;
        }

        String[] parts = raw.split(",");
        if (parts.length != 4) {
            return null;
        }

        World world = Bukkit.getWorld(parts[0]);
        if (world == null) {
            return null;
        }

        try {
            int x = Integer.parseInt(parts[1]);
            int y = Integer.parseInt(parts[2]);
            int z = Integer.parseInt(parts[3]);
            return new Location(world, x, y, z);
        } catch (NumberFormatException ex) {
            return null;
        }
    }

    private static final class RegionEntry {
        private final String regionNameLower;
        private final int maxActive;
        private final Map<String, BlockEntry> blocks = new HashMap<>();

        private RegionEntry(String regionName, int maxActive) {
            this.regionNameLower = regionName.toLowerCase(Locale.ROOT);
            this.maxActive = maxActive;
        }
    }

    private static final class BlockEntry {
        private final String blockIdentifier;
        private final double spawnChance;
        private final Material emptyBlock;
        private final List<Location> points;

        private BlockEntry(String blockIdentifier, double spawnChance, Material emptyBlock, List<Location> points) {
            this.blockIdentifier = blockIdentifier;
            this.spawnChance = spawnChance;
            this.emptyBlock = emptyBlock;
            this.points = points;
        }
    }

    private static final class PointMeta {
        private final Location location;
        private final Material emptyBlock;

        private PointMeta(Location location, Material emptyBlock) {
            this.location = location;
            this.emptyBlock = emptyBlock;
        }
    }

    private static final class RegionCycleDebug {
        private final String regionName;
        private final long cycleTimeMs;
        private final int totalPoints;
        private final int cap;
        private final int skippedBlacklist;
        private final int skippedMining;
        private final int skippedRegen;
        private final List<String> selected;

        private RegionCycleDebug(String regionName, long cycleTimeMs, int totalPoints, int cap,
                                 int skippedBlacklist, int skippedMining, int skippedRegen, List<String> selected) {
            this.regionName = regionName;
            this.cycleTimeMs = cycleTimeMs;
            this.totalPoints = totalPoints;
            this.cap = cap;
            this.skippedBlacklist = skippedBlacklist;
            this.skippedMining = skippedMining;
            this.skippedRegen = skippedRegen;
            this.selected = selected;
        }
    }
}

package me.allync.blockregen.task;

import me.allync.blockregen.BlockRegen;
import me.allync.blockregen.data.BlockData;
import me.allync.blockregen.data.MiningProgressState;
import me.allync.blockregen.data.MiningTargetKey;
import me.allync.blockregen.manager.MiningManager;
import me.allync.blockregen.util.BreakDurationHologramUtil;
import me.allync.blockregen.util.ModelEngineUtil;
import me.allync.blockregen.util.SoundUtil;
import org.bukkit.Location;
import org.bukkit.Material;
import org.bukkit.block.Block;
import org.bukkit.block.BlockState;
import org.bukkit.entity.Player;
import org.bukkit.inventory.ItemStack;
import org.bukkit.scheduler.BukkitRunnable;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.UUID;

/**
 * Per-player task untuk sistem penambangan kustom dengan durasi.
 *
 * Mendukung stackable blocks: jika ada blok berdampingan dengan tipe sama,
 * semua akan dibreak sekaligus saat penambangan selesai.
 *
 * Dipicu oleh RIGHT_CLICK_BLOCK (PlayerInteractEvent).
 */
public class PlayerMiningTask extends BukkitRunnable {

    private static final int SWING_INTERVAL_TICKS = 10; // lebih sering untuk feel right-click

    private final BlockRegen plugin;
    private final MiningManager miningManager;
    private final Player player;
    private final Block block;
    private final BlockData data;
    private final String blockIdentifier;
    private final BlockState originalState;
    private final long requiredTimeMs;
    private final Map<UUID, PlayerMiningTask> miningTasks;
    private final Map<MiningTargetKey, UUID> blockMiners;
    private final Map<MiningTargetKey, MiningProgressState> persistedProgress;
    private final MiningTargetKey blockKey;
    private final ItemStack initialToolSnapshot;
    private final boolean isHideBlockMode;
    /** Daftar blok stackable (termasuk blok utama di index 0). */
    private final List<Block> stackedBlocks;

    private long lastManualHitMs;
    private long accumulatedElapsedMs;
    private long lastProgressTickMs;
    private long lastOnTargetMs;

    private int currentStage = -1;
    private int swingTickCounter = 0;
    private boolean stateCleared = false;

    // ─── Constructor Lama (tanpa stacked, tanpa injectedState) ───────────────

    public PlayerMiningTask(
            BlockRegen plugin,
            Player player,
            Block block,
            BlockData data,
            String blockIdentifier,
            Map<UUID, PlayerMiningTask> miningTasks,
            Map<MiningTargetKey, UUID> blockMiners,
            Map<MiningTargetKey, MiningProgressState> persistedProgress,
            MiningTargetKey blockKey,
            long resumedElapsedMs
    ) {
        this(plugin, player, block, data, blockIdentifier, miningTasks, blockMiners,
                persistedProgress, blockKey, resumedElapsedMs, null, null);
    }

    // ─── Constructor dengan injectedOriginalState (hide-block, tanpa stacked) ─

    public PlayerMiningTask(
            BlockRegen plugin,
            Player player,
            Block block,
            BlockData data,
            String blockIdentifier,
            Map<UUID, PlayerMiningTask> miningTasks,
            Map<MiningTargetKey, UUID> blockMiners,
            Map<MiningTargetKey, MiningProgressState> persistedProgress,
            MiningTargetKey blockKey,
            long resumedElapsedMs,
            BlockState injectedOriginalState
    ) {
        this(plugin, player, block, data, blockIdentifier, miningTasks, blockMiners,
                persistedProgress, blockKey, resumedElapsedMs, injectedOriginalState, null);
    }

    // ─── Constructor UTAMA ────────────────────────────────────────────────────

    public PlayerMiningTask(
            BlockRegen plugin,
            Player player,
            Block block,
            BlockData data,
            String blockIdentifier,
            Map<UUID, PlayerMiningTask> miningTasks,
            Map<MiningTargetKey, UUID> blockMiners,
            Map<MiningTargetKey, MiningProgressState> persistedProgress,
            MiningTargetKey blockKey,
            long resumedElapsedMs,
            BlockState injectedOriginalState,
            List<Block> stackedBlocks
    ) {
        this.plugin = plugin;
        this.miningManager = plugin.getMiningManager();
        this.player = player;
        this.block = block;
        this.data = data;
        this.blockIdentifier = blockIdentifier;
        this.originalState = (injectedOriginalState != null) ? injectedOriginalState : block.getState();
        this.isHideBlockMode = (injectedOriginalState != null);
        this.miningTasks = miningTasks;
        this.blockMiners = blockMiners;
        this.persistedProgress = persistedProgress;
        this.blockKey = blockKey;
        this.initialToolSnapshot = normalizeItem(player.getInventory().getItemInMainHand());
        this.lastManualHitMs = System.currentTimeMillis();
        this.accumulatedElapsedMs = Math.max(0L, resumedElapsedMs);
        this.lastProgressTickMs = System.currentTimeMillis();
        this.lastOnTargetMs = this.lastProgressTickMs;
        this.requiredTimeMs = Math.max(50L, miningManager.calculateRequiredBreakTimeMs(player, data));

        // Salin daftar blok stackable; jika null, buat list kosong (hanya blok utama)
        if (stackedBlocks != null && !stackedBlocks.isEmpty()) {
            this.stackedBlocks = new ArrayList<>(stackedBlocks);
        } else {
            this.stackedBlocks = new ArrayList<>();
            this.stackedBlocks.add(block);
        }

        miningManager.markMining(this.block.getLocation());
    }

    // ─────────────────────────────────────────────────────────────────────────

    @Override
    public void run() {
        // 1. Player online?
        if (!player.isOnline()) {
            BreakDurationHologramUtil.remove(player);
            cancelTask();
            return;
        }

        // 2. Blok masih valid?
        String currentIdentifier = miningManager.getBlockIdentifier(block);
        boolean blockStillValid;
        if (currentIdentifier != null && currentIdentifier.equalsIgnoreCase("AIR")) {
            blockStillValid = ModelEngineUtil.isHiddenBlock(block.getLocation())
                    && originalState.getType() != Material.AIR;
        } else {
            blockStillValid = currentIdentifier != null && currentIdentifier.equalsIgnoreCase(blockIdentifier);
        }
        if (!blockStillValid) {
            miningManager.debug(player, blockIdentifier, "&cCancelling mining (Block already changed).");
            clearTaskState(true, false);
            return;
        }

        // 3. Pengecekan tambahan (jarak, gamemode, alat)
        long now = System.currentTimeMillis();
        boolean isOnTarget;
        if (isHideBlockMode) {
            double dist = player.getLocation().distance(block.getLocation().clone().add(0.5, 0.5, 0.5));
            isOnTarget = dist <= 5.0;
        } else {
            // Untuk mode otomatis, pemain harus terus melihat blok
            Block target = player.getTargetBlockExact(6);
            isOnTarget = target != null && target.getLocation().equals(block.getLocation());
        }

        if (!isOnTarget) {
            BreakDurationHologramUtil.remove(player);
            lastProgressTickMs = now;
            if (now - lastOnTargetMs >= plugin.getConfigManager().miningReleaseGraceMs) {
                miningManager.debug(player, blockIdentifier, "&cCancelling mining (Player too far).");
                cancelTask();
                return;
            }
            return;
        }
        lastOnTargetMs = now;

        if (player.getGameMode() != org.bukkit.GameMode.SURVIVAL) {
            miningManager.debug(player, blockIdentifier, "&cCancelling mining (Gamemode changed).");
            BreakDurationHologramUtil.remove(player);
            cancelTask();
            return;
        }

        if (hasToolChanged()) {
            miningManager.debug(player, blockIdentifier, "&cCancelling mining (Tool changed).");
            plugin.getBlockMiningListener().resetProgress(block.getLocation());
            cancelTask();
            return;
        }



        if (!isHoldingPickaxe()) {
            miningManager.debug(player, blockIdentifier, "&cCancelling mining (No valid tool in main hand).");
            String requiredTools = miningManager.formatRequiredTools(data);
            player.sendMessage(plugin.getConfigManager().wrongToolMessage.replace("%tool%", requiredTools));
            cancelTask();
            return;
        }

        // 4. Hitung progress
        long delta = Math.max(0L, now - lastProgressTickMs);
        accumulatedElapsedMs += delta;
        lastProgressTickMs = now;

        float progress = (float) accumulatedElapsedMs / (float) requiredTimeMs;

        // Update health bar hologram
        BreakDurationHologramUtil.update(player, block.getLocation(), progress, plugin);
        playWaitingSwingAnimation();

        if (progress >= 1.0f) {
            miningManager.debug(player, blockIdentifier, "Block break finished. Stack size: " + stackedBlocks.size());

            sendSafeBlockDamage(1.0f);

            if (isHideBlockMode) {
                ModelEngineUtil.removeModel(block.getLocation());
                ModelEngineUtil.restoreHiddenBlock(block.getLocation());
                miningManager.processBlockBreak(player, block, data, originalState, blockIdentifier);
            } else {
                // Hancurkan blok utama dulu
                breakBlock(block);
                // Hancurkan semua blok stackable lain (skip index 0 = blok utama)
                for (int i = 1; i < stackedBlocks.size(); i++) {
                    Block stacked = stackedBlocks.get(i);
                    // Pastikan blok masih ada dan belum berubah
                    String stackedId = miningManager.getBlockIdentifier(stacked);
                    if (stackedId.equalsIgnoreCase(blockIdentifier)
                            && !plugin.getRegenManager().isRegenerating(stacked.getLocation())) {
                        breakBlock(stacked);
                    }
                }
            }

            clearTaskState(true, false);
        } else {
            int newStage = (int) (progress * 10.0f);
            if (newStage != this.currentStage) {
                this.currentStage = newStage;
                sendSafeBlockDamage(progress);
            }
        }
    }

    /** Hancurkan satu blok melalui BlockBreakEvent (agar listener lain bisa hook). */
    private void breakBlock(Block target) {
        // Ambil state sebelum break
        BlockState state = target.getState();
        String id = miningManager.getBlockIdentifier(target);
        Set<String> regions = plugin.getRegionManager().getRegionNamesAt(target.getLocation());
        BlockData bd = plugin.getBlockManager().getBlockData(id, regions);
        if (bd == null) bd = data; // fallback ke data blok utama

        // Fire BlockBreakEvent dengan metadata agar BlockBreakListener tahu ini dari task
        target.setMetadata("blockregen-task-break", new org.bukkit.metadata.FixedMetadataValue(plugin, true));
        org.bukkit.event.block.BlockBreakEvent event = new org.bukkit.event.block.BlockBreakEvent(target, player);
        plugin.getServer().getPluginManager().callEvent(event);
        target.removeMetadata("blockregen-task-break", plugin);
    }


    public void cancelTask() {
        clearTaskState(true, true);
    }

    public Block getBlock() {
        return block;
    }

    private void clearTaskState(boolean resetCrackAnimation, boolean saveProgress) {
        if (stateCleared) return;
        stateCleared = true;

        if (!this.isCancelled()) this.cancel();
        miningTasks.remove(player.getUniqueId());
        blockMiners.computeIfPresent(blockKey, (key, owner) -> owner.equals(player.getUniqueId()) ? null : owner);

        if (saveProgress && accumulatedElapsedMs > 0L && accumulatedElapsedMs < requiredTimeMs) {
            persistedProgress.put(blockKey, new MiningProgressState(accumulatedElapsedMs, System.currentTimeMillis()));
        } else {
            persistedProgress.remove(blockKey);
        }

        BreakDurationHologramUtil.remove(player);
        SoundUtil.stopSoundToPlayer(player, data.getBreakSound(), plugin.getConfigManager().defaultBreakSound);
        miningManager.unmarkMining(block.getLocation());

        if (player.isOnline() && resetCrackAnimation) {
            sendSafeBlockDamage(0.0f);
        }
    }

    private void playWaitingSwingAnimation() {
        swingTickCounter++;
        if (swingTickCounter >= SWING_INTERVAL_TICKS) {
            swingTickCounter = 0;
            player.swingMainHand();
        }
    }

    private boolean isHoldingPickaxe() {
        if (data.requiresTool()) {
            for (var requirement : data.getRequiredTools()) {
                if (requirement.matches(player.getInventory().getItemInMainHand())) {
                    return true;
                }
            }
            return false;
        }
        Material material = player.getInventory().getItemInMainHand().getType();
        return material != Material.AIR && material.name().endsWith("_PICKAXE");
    }

    private boolean hasToolChanged() {
        ItemStack currentTool = normalizeItem(player.getInventory().getItemInMainHand());
        if (initialToolSnapshot == null && currentTool == null) return false;
        if (initialToolSnapshot == null || currentTool == null) return true;
        return !initialToolSnapshot.isSimilar(currentTool);
    }

    private ItemStack normalizeItem(ItemStack item) {
        if (item == null || item.getType() == Material.AIR) return null;
        ItemStack normalized = item.clone();
        normalized.setAmount(1);
        return normalized;
    }

    /** Dipanggil tiap klik kanan untuk reset timer "hold-timeout". */
    public void registerHit() {
        this.lastManualHitMs = System.currentTimeMillis();
        this.lastOnTargetMs = this.lastManualHitMs;
    }

    private void sendSafeBlockDamage(float progress) {
        float clamped = Math.max(0.0f, Math.min(1.0f, progress));
        for (Player onlinePlayer : block.getWorld().getPlayers()) {
            onlinePlayer.sendBlockDamage(block.getLocation(), clamped);
        }
    }

    public Location getBlockLocation() {
        return this.block.getLocation();
    }
}

